{
  "name": "wipeout-chaos",
  "private": true,
  "version": "1.0.0",
  "type": "module",
  "scripts": {
    "dev": "vite --host 0.0.0.0",
    "build": "vite build --base ./",
    "preview": "vite preview --host 0.0.0.0"
  },
  "dependencies": {
    "three": "^0.169.0"
  },
  "devDependencies": {
    "vite": "^5.4.8"
  }
}

@import url('https://fonts.googleapis.com/css2?family=Bungee&family=Outfit:wght@400;600;700;800;900&display=swap');

:root {
  --ink: #07192b;
  --deep: #0b2742;
  --sea: #0a6f88;
  --sky: #45d6ff;
  --sun: #ffd23f;
  --orange: #ff8a2b;
  --hot: #ff4d5e;
  --pink: #ff5fa2;
  --green: #6be675;
  --paper: #fffaf0;
  --shadow: 0 14px 0 rgba(0, 0, 0, .22), 0 24px 50px rgba(0, 0, 0, .35);
  --font-head: 'Bungee', Impact, sans-serif;
  --font-body: 'Outfit', system-ui, sans-serif;
}

* { box-sizing: border-box; -webkit-tap-highlight-color: transparent; }

html, body {
  margin: 0; padding: 0; height: 100%; overflow: hidden;
  background: #0a2438;
  font-family: var(--font-body);
  color: var(--paper);
  user-select: none;
  -webkit-user-select: none;
}

#game-canvas {
  position: fixed; inset: 0; width: 100%; height: 100%; display: block;
  touch-action: none;
}

#ui { position: fixed; inset: 0; pointer-events: none; z-index: 5; }
.screen { position: absolute; inset: 0; display: none; pointer-events: none; }
.screen.active { display: flex; }
.menu-screen { pointer-events: auto; align-items: center; justify-content: center; overflow: hidden; }
.menu-screen::before {
  content: ''; position: absolute; inset: 0;
  background: radial-gradient(circle at 70% 25%, rgba(53, 205, 255, .16), transparent 50%),
              linear-gradient(180deg, rgba(4, 17, 32, .3), rgba(4, 17, 32, .78));
  backdrop-filter: blur(2px);
}
.menu-screen > * { position: relative; z-index: 1; }

/* ---------- loading ---------- */
#loading {
  position: fixed; inset: 0; z-index: 50; display: flex; flex-direction: column;
  align-items: center; justify-content: center; gap: 18px;
  background: radial-gradient(circle at 50% 38%, #176b8c, #07192b 70%);
  transition: opacity .5s ease, visibility .5s;
}
#loading.gone { opacity: 0; visibility: hidden; }
.load-logo { font-family: var(--font-head); font-size: clamp(38px, 8vw, 72px); line-height: .9; text-align: center; transform: skew(-5deg); text-shadow: 0 6px 0 #08203a; }
.load-logo span { display: block; color: var(--sun); font-size: .62em; letter-spacing: .06em; }
.load-track { width: min(300px, 60vw); height: 14px; border-radius: 10px; background: rgba(255,255,255,.14); overflow: hidden; }
.load-track i { display: block; width: 100%; height: 100%; border-radius: 10px; background: linear-gradient(90deg, var(--orange), var(--sun)); animation: load 1.4s ease both; }
@keyframes load { from { width: 0 } to { width: 100% } }
#loading p { font-weight: 700; letter-spacing: .1em; font-size: 12px; opacity: .7; text-transform: uppercase; }

/* ---------- generic ---------- */
.btn {
  font-family: var(--font-head);
  border: 0; cursor: pointer; border-radius: 14px;
  padding: 13px 26px; font-size: 17px; letter-spacing: .05em;
  color: var(--paper); background: #17567a;
  box-shadow: 0 6px 0 #0b3550, 0 12px 22px rgba(0,0,0,.32);
  transform: translateY(0); transition: transform .12s, filter .12s, box-shadow .12s;
  text-shadow: 0 2px 0 rgba(0,0,0,.28);
}
.btn:hover { filter: brightness(1.12); transform: translateY(-2px); box-shadow: 0 8px 0 #0b3550, 0 16px 26px rgba(0,0,0,.35); }
.btn:active { transform: translateY(4px); box-shadow: 0 2px 0 #0b3550; }
.btn.primary { background: linear-gradient(180deg, #ffa63d, #ff6b2b); box-shadow: 0 6px 0 #b93c12, 0 14px 28px rgba(255, 107, 43, .35); }
.btn.primary:active { box-shadow: 0 2px 0 #b93c12; }
.btn.ghost { background: transparent; box-shadow: none; border: 2px solid rgba(255,255,255,.3); }
.btn.ghost:hover { background: rgba(255,255,255,.08); box-shadow: none; }
.btn:disabled { opacity: .42; cursor: not-allowed; transform: none; filter: grayscale(.6); }
.icon-btn {
  background: rgba(4, 24, 39, .6); border: 2px solid rgba(255,255,255,.22); color: white;
  width: 46px; height: 46px; border-radius: 13px; font-size: 15px; cursor: pointer;
}
.back-btn {
  width: 46px; height: 46px; flex: 0 0 46px; border-radius: 13px; border: 0;
  background: rgba(255,255,255,.12); color: white; font-size: 30px; line-height: 1; cursor: pointer;
  padding-bottom: 4px; pointer-events: auto;
}
.back-btn:hover { background: rgba(255,255,255,.22); }
.token-pill {
  font-weight: 800; font-size: 14px; padding: 8px 14px; border-radius: 30px;
  background: rgba(255, 210, 63, .14); border: 2px solid rgba(255, 210, 63, .45);
  color: var(--sun); white-space: nowrap;
}

/* ---------- title ---------- */
#screen-title { justify-content: flex-start; align-items: center; }
#screen-title::before { background: linear-gradient(90deg, rgba(4,17,32,.86) 0%, rgba(4,17,32,.5) 45%, rgba(4,17,32,0) 75%); backdrop-filter: none; }
.title-wrap { margin-left: clamp(22px, 7vw, 110px); max-width: 640px; display: flex; flex-direction: column; gap: 18px; }
.logo { position: relative; transform: skew(-6deg) rotate(-1.5deg); display: inline-flex; flex-direction: column; filter: drop-shadow(0 10px 0 rgba(0,0,0,.25)); }
.logo-top {
  font-family: var(--font-head); font-size: clamp(52px, 11vw, 124px); line-height: .82;
  color: #fff; letter-spacing: -.02em;
  -webkit-text-stroke: clamp(3px, .7vw, 8px) #0b2136;
  text-shadow: 0 8px 0 #0b2136, 0 14px 0 rgba(0,0,0,.2);
  background: linear-gradient(180deg, #fff 15%, #c9f5ff 55%, #6fe0ff 100%);
  -webkit-background-clip: text; background-clip: text;
}
.logo-bottom {
  font-family: var(--font-head); font-size: clamp(44px, 9vw, 102px); line-height: .82;
  color: var(--sun); letter-spacing: .02em; align-self: flex-end; margin-right: 4%;
  -webkit-text-stroke: clamp(3px, .6vw, 7px) #5b2500;
  text-shadow: 0 9px 0 #5b2500, 0 14px 24px rgba(0,0,0,.4);
}
.logo-tag {
  align-self: flex-end; margin: 10px 5% 0 0; font-weight: 900; letter-spacing: .32em; font-size: clamp(9px, 1.4vw, 13px);
  color: #ffdf9a; background: rgba(0,0,0,.25); padding: 5px 9px 5px 13px; border-radius: 5px;
}
.title-sub { margin: 0; font-size: clamp(14px, 2vw, 19px); font-weight: 600; color: #bfe9f7; max-width: 430px; text-shadow: 0 2px 8px rgba(0,0,0,.5); }
.menu-buttons { display: grid; gap: 11px; width: min(330px, 78vw); margin-top: 6px; }
.menu-buttons .btn { padding: 15px 26px; font-size: 19px; text-align: left; }
.title-footer { display: flex; align-items: center; gap: 14px; margin-top: 6px; flex-wrap: wrap; }
.tiny { font-size: 11px; color: rgba(255,255,255,.55); max-width: 270px; line-height: 1.35; }

/* ---------- panels ---------- */
.panel {
  width: min(640px, 94vw); max-height: 92vh; overflow-y: auto; overscroll-behavior: contain;
  background: linear-gradient(180deg, rgba(10, 38, 61, .94), rgba(5, 25, 42, .96));
  border: 2px solid rgba(92, 202, 235, .3); border-radius: 26px;
  padding: clamp(18px, 3vw, 32px);
  box-shadow: 0 30px 80px rgba(0,0,0,.55), inset 0 1px 0 rgba(255,255,255,.1);
  scrollbar-width: thin; scrollbar-color: #2a7c9e transparent;
}
.panel.wide { width: min(1020px, 95vw); }
.panel.narrow { width: min(420px, 92vw); }
.panel::-webkit-scrollbar { width: 7px; }
.panel::-webkit-scrollbar-thumb { background: #2a7c9e; border-radius: 8px; }
.panel-head { display: flex; align-items: center; gap: 14px; margin-bottom: 20px; }
.panel-head > div { flex: 1; min-width: 0; }
.panel-head h2 { font-family: var(--font-head); font-size: clamp(22px, 3.2vw, 32px); margin: 0; line-height: 1; letter-spacing: .01em; }
.panel-head p { margin: 6px 0 0; font-size: 13px; color: #93c8dc; font-weight: 600; }
h2 { font-family: var(--font-head); }

/* ---------- mode cards ---------- */
.mode-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 14px; }
.mode-card {
  text-align: left; border: 2px solid rgba(255,255,255,.1); border-radius: 18px;
  background: linear-gradient(160deg, rgba(28, 88, 120, .7), rgba(8, 35, 56, .9));
  padding: 18px; cursor: pointer; color: var(--paper); font-family: var(--font-body);
  transition: transform .14s, border-color .14s, background .14s;
  position: relative; overflow: hidden; pointer-events: auto;
}
.mode-card::after {
  content: attr(data-emoji); position: absolute; right: -8px; bottom: -18px; font-size: 74px; opacity: .18; transform: rotate(-12deg);
}
.mode-card:hover { transform: translateY(-3px); border-color: var(--sun); background: linear-gradient(160deg, rgba(38, 114, 150, .8), rgba(8, 35, 56, .9)); }
.mode-card h3 { font-family: var(--font-head); font-size: 19px; margin: 0 0 6px; color: var(--sun); }
.mode-card p { margin: 0; font-size: 12.5px; line-height: 1.45; color: #b5d9e8; min-height: 38px; }
.mode-card .mode-meta { margin-top: 12px; font-size: 10px; font-weight: 800; letter-spacing: .12em; color: #7fd8f5; text-transform: uppercase; }
.mode-card.locked { opacity: .55; cursor: not-allowed; }
.mode-card.locked:hover { transform: none; border-color: rgba(255,255,255,.1); }

/* ---------- setup ---------- */
.setup-selected { display: flex; gap: 16px; align-items: center; background: rgba(255,255,255,.05); border-radius: 18px; padding: 14px 16px; margin-bottom: 16px; border: 1px solid rgba(255,255,255,.08); }
.char-preview { width: 92px; height: 112px; flex: 0 0 92px; border-radius: 14px; background: radial-gradient(circle at 50% 30%, #2b8cb3, #0a2b42); overflow: hidden; position: relative; }
.char-preview.large { width: 100%; height: 190px; flex: none; }
.char-preview canvas { width: 100% !important; height: 100% !important; display: block; }
.setup-char-info { flex: 1; min-width: 0; }
.setup-char-info h3 { font-family: var(--font-head); margin: 0; font-size: 22px; }
.setup-char-info p { margin: 4px 0 8px; font-size: 12px; color: #9ed3e6; font-style: italic; }
.stat-list { display: grid; grid-template-columns: 1fr 1fr; gap: 4px 16px; }
.stat-row { display: flex; align-items: center; gap: 8px; font-size: 10px; font-weight: 800; letter-spacing: .08em; color: #b9dfed; }
.stat-row span { width: 62px; flex: 0 0 62px; }
.stat-row .bar { flex: 1; height: 6px; border-radius: 4px; background: rgba(255,255,255,.12); overflow: hidden; }
.stat-row .bar i { display: block; height: 100%; border-radius: 4px; background: linear-gradient(90deg, #4bd2ff, #ffd23f); }
.setup-options { display: flex; flex-wrap: wrap; gap: 8px; margin-bottom: 18px; }
.opt-group { flex: 1; min-width: 220px; }
.opt-group > label { display: block; font-size: 10px; font-weight: 800; letter-spacing: .14em; color: #7fb8cd; margin-bottom: 6px; }
.opt-pills { display: flex; flex-wrap: wrap; gap: 6px; }
.opt-pill {
  border: 1.5px solid rgba(255,255,255,.16); background: rgba(255,255,255,.05); color: #d8eef6;
  padding: 8px 13px; border-radius: 10px; font-size: 12px; font-weight: 700; cursor: pointer; font-family: var(--font-body);
}
.opt-pill.active { background: var(--sun); color: #3d2500; border-color: var(--sun); }
.opt-pill:disabled { opacity: .35; cursor: not-allowed; }
.big-btn { width: 100%; padding: 17px; font-size: 22px; }

/* ---------- roster ---------- */
.roster-layout { display: grid; grid-template-columns: minmax(0, 1.45fr) minmax(230px, .8fr); gap: 20px; align-items: start; }
.roster-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(96px, 1fr)); gap: 9px; max-height: 60vh; overflow-y: auto; padding-right: 4px; }
.roster-card {
  border-radius: 13px; border: 2px solid rgba(255,255,255,.1); background: rgba(14, 52, 77, .8);
  padding: 7px; cursor: pointer; text-align: center; color: white; font-family: var(--font-body);
  position: relative; transition: transform .12s, border-color .12s;
}
.roster-card:hover { transform: translateY(-2px); border-color: #6fd4f2; }
.roster-card.selected { border-color: var(--sun); box-shadow: 0 0 0 2px rgba(255,210,63,.3); }
.roster-card.locked-char { opacity: .55; }
.roster-card .rc-body { height: 66px; border-radius: 8px; background: radial-gradient(circle at 50% 20%, rgba(88,180,214,.35), rgba(0,0,0,.25)); overflow: hidden; }
.roster-card canvas { width: 100% !important; height: 100% !important; }
.roster-card b { display: block; font-size: 10px; margin-top: 5px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.roster-card .rc-lock { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; font-size: 24px; background: rgba(3,15,26,.45); border-radius: 11px; }
.roster-side { background: rgba(255,255,255,.04); border: 1px solid rgba(255,255,255,.08); border-radius: 18px; padding: 14px; position: sticky; top: 0; }
.roster-side h3 { font-family: var(--font-head); margin: 10px 0 2px; font-size: 21px; }
.roster-tag { font-size: 11.5px; color: #9ed3e6; font-style: italic; margin: 0 0 9px; min-height: 30px; }
.custom-row { margin-top: 12px; }
.custom-row label { display: block; font-size: 9px; letter-spacing: .14em; font-weight: 800; color: #7fb8cd; margin-bottom: 6px; }
.swatches, .accessories { display: flex; flex-wrap: wrap; gap: 6px; }
.swatch { width: 24px; height: 24px; border-radius: 50%; border: 2px solid rgba(255,255,255,.5); cursor: pointer; padding: 0; }
.swatch.active { border-color: #fff; box-shadow: 0 0 0 2px var(--ink), 0 0 0 4px var(--sun); }
.acc-btn { border: 1.5px solid rgba(255,255,255,.14); border-radius: 8px; background: rgba(255,255,255,.06); color: #cdeaf4; font-size: 10px; font-weight: 800; padding: 5px 8px; cursor: pointer; }
.acc-btn.active { background: var(--sun); color: #3d2500; }
.lock-note { font-size: 11px; color: var(--sun); margin: 8px 0 0; min-height: 14px; }

/* ---------- leaderboard ---------- */
.tabs { display: flex; gap: 6px; flex-wrap: wrap; margin-bottom: 14px; }
.tab { border: 1.5px solid rgba(255,255,255,.14); background: rgba(255,255,255,.05); color: #b7dceb; border-radius: 9px; padding: 7px 12px; font-size: 11px; font-weight: 800; cursor: pointer; font-family: var(--font-body); }
.tab.active { background: var(--sun); color: #3d2500; border-color: var(--sun); }
.leaderboard-body { min-height: 210px; }
.lb-empty { text-align: center; padding: 54px 20px; color: #7fa9ba; font-size: 13px; font-weight: 600; }
.lb-row { display: grid; grid-template-columns: 42px 1fr auto auto; gap: 10px; align-items: center; padding: 10px 12px; border-radius: 10px; margin-bottom: 5px; background: rgba(255,255,255,.045); font-size: 13px; }
.lb-row.me { background: rgba(255, 210, 63, .12); border: 1px solid rgba(255,210,63,.3); }
.lb-row .lb-pos { font-family: var(--font-head); color: var(--sun); font-size: 14px; }
.lb-row .lb-name { font-weight: 700; }
.lb-row .lb-char { font-size: 10px; color: #8ec5d9; }
.lb-row .lb-time { font-family: var(--font-head); font-size: 14px; }

/* ---------- how to ---------- */
.howto-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; margin-bottom: 18px; }
.howto-grid div { background: rgba(255,255,255,.05); border-radius: 12px; padding: 12px 14px; }
.howto-grid b { display: block; font-family: var(--font-head); color: var(--sun); font-size: 13px; margin-bottom: 4px; }
.howto-grid span { font-size: 12px; line-height: 1.45; color: #b8d9e6; }

/* ---------- results ---------- */
.results-head { text-align: center; margin-bottom: 15px; }
#results-kicker, #standings-kicker { font-size: 10px; font-weight: 900; letter-spacing: .24em; color: #7fd8f5; }
.results-head h2 { font-family: var(--font-head); font-size: clamp(28px, 5vw, 46px); margin: 5px 0; color: var(--sun); line-height: 1; }
.results-head p { margin: 0; color: #a8cfdd; font-size: 13px; }
.results-stats { display: grid; grid-template-columns: repeat(4, 1fr); gap: 8px; margin-bottom: 15px; }
.results-stats div { background: rgba(255,255,255,.055); padding: 10px; border-radius: 12px; text-align: center; }
.results-stats span { display: block; font-size: 9px; font-weight: 800; letter-spacing: .14em; color: #7fb8cd; }
.results-stats b { font-family: var(--font-head); font-size: 20px; color: white; }
.results-table { max-height: 30vh; overflow-y: auto; margin-bottom: 12px; }
.results-unlocks { display: flex; flex-wrap: wrap; gap: 6px; justify-content: center; margin-bottom: 12px; }
.unlock-pill { background: rgba(255, 210, 63, .16); border: 1px solid rgba(255,210,63,.4); color: var(--sun); font-size: 11px; font-weight: 800; padding: 6px 10px; border-radius: 20px; }
.results-buttons { display: flex; gap: 8px; justify-content: center; flex-wrap: wrap; }

/* ---------- pause ---------- */
.overlay { background: rgba(2, 10, 19, .66); backdrop-filter: blur(6px); }
.pause-sub { text-align: center; color: #9cc9db; font-size: 12.5px; margin: -8px 0 22px; }
.pause-buttons { display: grid; gap: 9px; margin-bottom: 16px; }
.pause-toggles { display: flex; flex-direction: column; gap: 7px; font-size: 11px; font-weight: 700; color: #a9d2e2; }
.pause-toggles label { display: flex; align-items: center; gap: 8px; cursor: pointer; }
.pause-toggles input { accent-color: var(--sun); width: 15px; height: 15px; }

/* ---------- HUD ---------- */
#hud { align-items: stretch; justify-content: flex-start; padding: max(10px, env(safe-area-inset-top)) max(12px, env(safe-area-inset-right)) max(10px, env(safe-area-inset-bottom)) max(12px, env(safe-area-inset-left)); }
.hud-top { display: flex; align-items: flex-start; justify-content: space-between; gap: 12px; width: 100%; }
.hud-left { display: flex; align-items: center; gap: 10px; }
.hud-round { display: flex; flex-direction: column; text-shadow: 0 2px 6px rgba(0,0,0,.6); }
.hud-round span { font-size: 9px; font-weight: 900; letter-spacing: .18em; color: #8be2ff; }
.hud-round b { font-family: var(--font-head); font-size: clamp(13px, 2.4vw, 18px); color: #fff; }
.hud-center { text-align: center; position: absolute; left: 50%; transform: translateX(-50%); top: max(8px, env(safe-area-inset-top)); width: min(46vw, 340px); }
#hud-timer { font-family: var(--font-head); font-size: clamp(20px, 3.4vw, 30px); text-shadow: 0 3px 0 rgba(0,0,0,.4); letter-spacing: .02em; }
.hud-progress { height: 8px; border-radius: 6px; background: rgba(0,0,0,.4); position: relative; margin-top: 4px; border: 1px solid rgba(255,255,255,.18); }
.hud-progress i { position: absolute; inset: 0 auto 0 0; width: 0%; background: linear-gradient(90deg, #37d5ff, #ffe14a); border-radius: 5px; transition: width .2s; }
.hud-progress span { position: absolute; top: -5px; width: 8px; height: 16px; border-radius: 4px; background: #fff; box-shadow: 0 0 8px #fff; transform: translateX(-50%); left: 0%; transition: left .2s; }
#hud-position { font-size: 10px; font-weight: 900; letter-spacing: .15em; color: #ffd23f; margin-top: 3px; text-shadow: 0 2px 4px rgba(0,0,0,.7); }
.hud-right { display: flex; flex-direction: column; align-items: flex-end; gap: 5px; }
.splash-pips { display: flex; gap: 4px; }
.splash-pips i { width: 17px; height: 17px; border-radius: 50%; background: rgba(0,0,0,.36); border: 2px solid rgba(255,255,255,.3); display: block; }
.splash-pips i.used { background: #ff4d5e; border-color: #ff9aa4; box-shadow: 0 0 8px #ff4d5e; }
.checkpoint-tag { font-size: 9px; font-weight: 900; letter-spacing: .14em; color: #9fffb6; background: rgba(10, 50, 30, .65); border: 1px solid rgba(120, 255, 160, .4); padding: 3px 8px; border-radius: 20px; }
.hud-feed { position: absolute; top: 70px; right: 14px; display: flex; flex-direction: column; gap: 4px; align-items: flex-end; }
.feed-item { background: rgba(4, 20, 33, .72); border-left: 3px solid var(--sun); padding: 5px 10px; border-radius: 6px; font-size: 10px; font-weight: 700; color: #d7f0f8; animation: feedIn .35s ease; }
.feed-item.bad { border-left-color: var(--hot); }
.feed-item.good { border-left-color: var(--green); }
@keyframes feedIn { from { transform: translateX(30px); opacity: 0 } }
.hud-bonus { position: absolute; left: 50%; top: 26%; transform: translateX(-50%); font-family: var(--font-head); font-size: clamp(20px, 4vw, 36px); color: var(--sun); text-shadow: 0 4px 0 #7a3e00, 0 8px 24px rgba(0,0,0,.5); opacity: 0; pointer-events: none; text-align: center; }
.hud-bonus.show { animation: bonusPop 1.1s ease both; }
@keyframes bonusPop { 0% { opacity: 0; transform: translateX(-50%) scale(.6) rotate(-4deg) } 20% { opacity: 1; transform: translateX(-50%) scale(1.15) rotate(1deg) } 75% { opacity: 1; transform: translateX(-50%) scale(1) } 100% { opacity: 0; transform: translateX(-50%) scale(1.05) translateY(-14px) } }
.hud-bottom { position: absolute; left: 50%; bottom: max(10px, env(safe-area-inset-bottom)); transform: translateX(-50%); display: flex; flex-direction: column; align-items: center; gap: 5px; width: 150px; }
.stamina-wrap { width: 100%; }
.stamina-label { font-size: 8px; font-weight: 900; letter-spacing: .16em; color: #9ad9ee; text-align: center; margin-bottom: 3px; text-shadow: 0 1px 3px #000; }
.stamina-bar { height: 7px; background: rgba(0,0,0,.45); border-radius: 5px; overflow: hidden; border: 1px solid rgba(255,255,255,.15); }
.stamina-bar i { display: block; height: 100%; width: 100%; background: linear-gradient(90deg, #6be675, #d6ff5c); transition: width .08s linear; }
.stamina-bar i.low { background: linear-gradient(90deg, #ff6b2b, #ff4d5e); }
.hud-speed { font-size: 9px; font-weight: 700; color: #b9e3f1; text-shadow: 0 1px 4px #000; letter-spacing: .06em; }
.hud-speed b { font-family: var(--font-head); font-size: 14px; color: white; }
.countdown { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; font-family: var(--font-head); font-size: clamp(70px, 16vw, 150px); color: var(--sun); text-shadow: 0 8px 0 #8d3a00, 0 16px 50px rgba(0,0,0,.6); pointer-events: none; opacity: 0; }
.countdown.tick { animation: countPop .9s ease both; }
@keyframes countPop { 0% { opacity: 0; transform: scale(1.6) rotate(-6deg) } 25% { opacity: 1; transform: scale(1) rotate(0) } 75% { opacity: 1 } 100% { opacity: 0; transform: scale(.85) } }
.splash-flash { position: absolute; inset: 0; background: radial-gradient(circle, transparent 25%, rgba(20, 160, 220, .55)); opacity: 0; pointer-events: none; }
.splash-flash.go { animation: flash .7s ease; }
@keyframes flash { 0% { opacity: 0 } 20% { opacity: 1 } 100% { opacity: 0 } }
.desktop-hint { position: absolute; bottom: 8px; left: 50%; transform: translateX(-50%); font-size: 9px; color: rgba(255,255,255,.4); white-space: nowrap; display: block; }

/* ---------- touch controls ---------- */
#touch-controls { position: absolute; inset: auto 0 0 0; height: 0; }
#joystick {
  position: fixed; left: max(18px, env(safe-area-inset-left)); bottom: max(24px, env(safe-area-inset-bottom));
  width: 128px; height: 128px; border-radius: 50%;
  background: rgba(4, 24, 39, .28); border: 2px solid rgba(255,255,255,.18);
  touch-action: none; pointer-events: auto; opacity: .92;
}
#joystick-base { position: absolute; inset: 18px; border-radius: 50%; border: 2px dashed rgba(255,255,255,.16); }
#joystick-knob {
  position: absolute; left: 50%; top: 50%; width: 56px; height: 56px; margin: -28px 0 0 -28px;
  border-radius: 50%; background: radial-gradient(circle at 35% 30%, #f5fbff, #7fc6dc);
  box-shadow: 0 4px 12px rgba(0,0,0,.4), inset 0 -3px 0 rgba(0,0,0,.15);
  border: 2px solid rgba(255,255,255,.7);
}
.touch-buttons {
  position: fixed; right: max(16px, env(safe-area-inset-right)); bottom: max(22px, env(safe-area-inset-bottom));
  display: grid; grid-template-columns: 66px 78px; grid-template-rows: 66px 78px; gap: 8px;
  align-items: end; justify-items: center; pointer-events: none;
}
.touch-btn {
  border-radius: 50%; border: 2px solid rgba(255,255,255,.5); font-family: var(--font-head);
  color: #fff; pointer-events: auto; touch-action: none; padding: 0; cursor: pointer;
  text-shadow: 0 2px 3px rgba(0,0,0,.4); display: flex; align-items: center; justify-content: center;
  box-shadow: 0 5px 0 rgba(0,0,0,.3), 0 8px 16px rgba(0,0,0,.28);
  transition: transform .08s;
}
.touch-btn:active, .touch-btn.pressed { transform: scale(.93); }
.touch-btn span { font-size: 10px; letter-spacing: .03em; }
.touch-btn.big { width: 78px; height: 78px; grid-column: 2; grid-row: 1 / span 2; align-self: end; background: linear-gradient(180deg, #ffb44d, #ff5b2b); font-size: 13px; }
.touch-btn.medium { width: 66px; height: 66px; grid-column: 1; grid-row: 1; background: linear-gradient(180deg, #42d4ff, #127dab); }
.touch-btn.small { width: 56px; height: 56px; grid-column: 1; grid-row: 2; justify-self: end; background: linear-gradient(180deg, #b18cff, #6b3ddb); }
.touch-btn.small span { font-size: 9px; }
body.no-touch #touch-controls { display: none; }
body.low-gfx .menu-screen::before { backdrop-filter: none; }

@media (pointer: fine) and (min-width: 900px) {
  #joystick, .touch-buttons { display: none; }
}
@media (max-width: 760px) {
  .desktop-hint { display: none; }
  .roster-layout { grid-template-columns: 1fr; }
  .roster-grid { max-height: 34vh; grid-template-columns: repeat(auto-fill, minmax(78px, 1fr)); }
  .roster-side { position: static; }
  .char-preview.large { height: 130px; }
  .stat-list { grid-template-columns: 1fr 1fr; }
  .mode-grid { grid-template-columns: 1fr 1fr; }
  .mode-card { padding: 12px; }
  .mode-card p { min-height: 50px; font-size: 11px; }
  .howto-grid { grid-template-columns: 1fr; }
  .results-stats { grid-template-columns: 1fr 1fr; }
  .panel { max-height: 94vh; border-radius: 20px; }
  .setup-selected { padding: 10px; }
  .char-preview { width: 70px; height: 86px; flex-basis: 70px; }
  .panel-head { margin-bottom: 12px; }
  .title-wrap { margin-left: 5vw; gap: 12px; }
  .title-footer { display: none; }
  .hud-bottom { width: 110px; bottom: 6px; }
  .hud-feed { top: 64px; }
}
@media (max-width: 420px) {
  .mode-grid { grid-template-columns: 1fr; }
  .mode-card p { min-height: 0; }
  .hud-center { width: 42vw; top: 6px; }
  .splash-pips i { width: 14px; height: 14px; }
  .checkpoint-tag { display: none; }
  #joystick { width: 112px; height: 112px; }
  #joystick-knob { width: 48px; height: 48px; margin: -24px 0 0 -24px; }
  .touch-buttons { grid-template-columns: 58px 68px; grid-template-rows: 58px 68px; }
  .touch-btn.medium { width: 58px; height: 58px; }
  .touch-btn.big { width: 68px; height: 68px; }
  .touch-btn.small { width: 50px; height: 50px; }
  .results-buttons .btn { padding: 11px 17px; font-size: 14px; }
}
@media (max-height: 500px) and (orientation: landscape) {
  #joystick { width: 96px; height: 96px; left: 12px; bottom: 12px; }
  #joystick-knob { width: 44px; height: 44px; margin: -22px 0 0 -22px; }
  .touch-buttons { grid-template-columns: 50px 60px; grid-template-rows: 50px 60px; right: 12px; bottom: 12px; }
  .touch-btn.medium { width: 50px; height: 50px; }
  .touch-btn.big { width: 60px; height: 60px; }
  .touch-btn.small { width: 44px; height: 44px; }
  .hud-bottom { display: none; }
  .panel { max-height: 96vh; }
  .roster-grid { max-height: 46vh; }
  .char-preview.large { height: 110px; }
  .stat-list { gap: 2px 10px; }
}

