// Tiny WebAudio synth: no audio files, no load time, all cartoon noises.
export const audio = {
  ctx: null,
  master: null,
  muted: false,
  enabled: false,

  init() {
    if (this.ctx) { if (this.ctx.state === 'suspended') this.ctx.resume(); return; }
    const Ctx = window.AudioContext || window.webkitAudioContext;
    if (!Ctx) return;
    this.ctx = new Ctx();
    this.master = this.ctx.createGain();
    this.master.gain.value = 0.55;
    this.master.connect(this.ctx.destination);
    this.enabled = true;
  },

  setMuted(m) {
    this.muted = m;
    if (this.master) this.master.gain.value = m ? 0 : 0.55;
  },

  tone(freq, dur, type = 'sine', vol = 0.25, slideTo = null, delay = 0) {
    if (!this.ctx || this.muted) return;
    const t = this.ctx.currentTime + delay;
    const osc = this.ctx.createOscillator();
    const g = this.ctx.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, t);
    if (slideTo) osc.frequency.exponentialRampToValueAtTime(Math.max(20, slideTo), t + dur);
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(vol, t + 0.012);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    osc.connect(g); g.connect(this.master);
    osc.start(t); osc.stop(t + dur + 0.03);
  },

  noise(dur, vol = 0.25, filterFreq = 900, type = 'lowpass', delay = 0) {
    if (!this.ctx || this.muted) return;
    const t = this.ctx.currentTime + delay;
    const len = Math.max(1, Math.floor(this.ctx.sampleRate * dur));
    const buf = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
    const data = buf.getChannelData(0);
    for (let i = 0; i < len; i++) data[i] = (Math.random() * 2 - 1) * (1 - i / len);
    const src = this.ctx.createBufferSource();
    src.buffer = buf;
    const filter = this.ctx.createBiquadFilter();
    filter.type = type; filter.frequency.value = filterFreq;
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(vol, t);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    src.connect(filter); filter.connect(g); g.connect(this.master);
    src.start(t);
  },

  click() { this.tone(520, 0.07, 'square', 0.12); },
  select() { this.tone(660, 0.09, 'triangle', 0.16, 880); },
  countdown(n) {
    if (n > 0) this.tone(440, 0.16, 'square', 0.2);
    else { this.tone(880, 0.35, 'square', 0.22, 1320); this.tone(1320, 0.3, 'triangle', 0.12, 1760, 0.04); }
  },
  jump() { this.tone(300, 0.16, 'sine', 0.18, 620); },
  land(force = 1) { this.tone(90, 0.12, 'sine', 0.14 * Math.min(1.6, force)); this.noise(0.08, 0.1, 500); },
  dive() { this.noise(0.32, 0.16, 1400, 'bandpass'); this.tone(220, 0.2, 'sawtooth', 0.08, 110); },
  hit() {
    this.noise(0.22, 0.3, 700);
    this.tone(140, 0.22, 'square', 0.2, 60);
    this.tone(300, 0.1, 'triangle', 0.1, 180);
  },
  splash() {
    this.noise(0.65, 0.42, 1800, 'bandpass');
    this.noise(0.5, 0.25, 600);
    this.tone(500, 0.4, 'sine', 0.1, 100);
  },
  checkpoint() {
    this.tone(660, 0.12, 'triangle', 0.2);
    this.tone(880, 0.16, 'triangle', 0.2, null, 0.1);
    this.tone(1320, 0.25, 'triangle', 0.18, null, 0.2);
  },
  launch() { this.tone(160, 0.32, 'sine', 0.28, 900); this.tone(260, 0.25, 'triangle', 0.12, 1300, 0.03); },
  finish() {
    const notes = [523, 659, 784, 1047, 1319];
    notes.forEach((n, i) => this.tone(n, 0.28, 'triangle', 0.22, null, i * 0.11));
    this.tone(1568, 0.7, 'triangle', 0.16, null, 0.55);
  },
  fail() {
    [392, 330, 262, 196].forEach((n, i) => this.tone(n, 0.3, 'square', 0.16, null, i * 0.16));
  },
  coin() { this.tone(1046, 0.08, 'square', 0.16); this.tone(1568, 0.12, 'square', 0.15, null, 0.07); },
  crowd(level = 1) {
    if (!this.ctx || this.muted) return;
    this.noise(1.4, 0.1 * level, 900, 'bandpass');
  }
};

import { CHARACTERS } from './characters.js';

const KEY = 'wipeout-chaos-save-v2';
const FREE = CHARACTERS.filter(c => c.unlock.free).map(c => c.id);

export const save = {
  data: null,

  defaults() {
    return {
      tokens: 0,
      unlocked: FREE.slice(),
      selected: 'tina',
      costumeColor: 0,
      accessory: 'none',
      careerRound: 1,
      careerWins: 0,
      careerDone: false,
      championshipBest: 0,
      endlessBest: 0,
      totalRuns: 0,
      bestTimes: {},
      leaderboards: {},
      muted: false,
      lowGfx: false
    };
  },

  load() {
    try {
      const raw = localStorage.getItem(KEY);
      this.data = raw ? { ...this.defaults(), ...JSON.parse(raw) } : this.defaults();
    } catch {
      this.data = this.defaults();
    }
    for (const id of FREE) if (!this.data.unlocked.includes(id)) this.data.unlocked.push(id);
    return this.data;
  },

  persist() {
    try { localStorage.setItem(KEY, JSON.stringify(this.data)); } catch {}
  },

  reset() { this.data = this.defaults(); this.persist(); },

  unlock(id) {
    if (!this.data.unlocked.includes(id)) {
      this.data.unlocked.push(id);
      this.persist();
      return true;
    }
    return false;
  },

  addTokens(n) {
    this.data.tokens = Math.max(0, this.data.tokens + n);
    this.persist();
  },

  spendTokens(n) {
    if (this.data.tokens < n) return false;
    this.data.tokens -= n;
    this.persist();
    return true;
  },

  addResult(mode, round, arena, entry) {
    const key = `${mode}:${round}:${arena}`;
    const list = this.data.leaderboards[key] || [];
    list.push(entry);
    list.sort((a, b) => a.time - b.time);
    this.data.leaderboards[key] = list.slice(0, 20);
    if (mode === 'timeTrial') {
      const bestKey = `${round}:${arena}`;
      if (!this.data.bestTimes[bestKey] || entry.time < this.data.bestTimes[bestKey]) {
        this.data.bestTimes[bestKey] = entry.time;
      }
    }
    this.persist();
  },

  leaderboard(mode, round, arena) {
    return this.data.leaderboards[`${mode}:${round}:${arena}`] || [];
  }
};

import * as THREE from 'three';
import { buildCharacterMesh } from './characterRig.js';
import { randomBotCharacters, BOT_NAMES } from './characters.js';

// AI rivals are real characters running the same course on a timing rail.
// They are competitors for position, never substitute for player control.
export function createBots(course, playerCharacterId, count = 7) {
  const chars = randomBotCharacters(playerCharacterId, count);
  const bots = [];
  const startZ = course.startZ;
  const totalDistance = Math.abs(course.finishZ - startZ);

  const par = course.parTime;
  const times = [];
  for (let i = 0; i < count; i++) {
    // spread finishers from quick to hopeless, with a little seeded variety
    const factor = 0.86 + (i / Math.max(1, count - 1)) * 0.36;
    times.push(par * factor);
  }
  // shuffle so rank isn't tied to lane
  times.sort(() => Math.random() - 0.5);

  for (let i = 0; i < count; i++) {
    const c = chars[i % chars.length];
    const rig = buildCharacterMesh(c, { detail: false, costume: c.colors.shirt, accessory: c.accessory });
    const g = new THREE.Group();
    g.add(rig.root);
    course.group.add(g);
    const lane = [-4.6, 4.6, -2.3, 2.3, -5.4, 5.4, 0.6][i % 7];
    const bot = {
      id: 'bot' + i,
      name: `${BOT_NAMES[i % BOT_NAMES.length]} ${i + 1}`,
      character: c,
      rig, group: g,
      finishTime: times[i],
      idealFinish: times[i],
      laneOffset: lane,
      progress: 0,
      z: startZ,
      y: 0,
      prevY: 0,
      finished: false,
      rank: i + 1,
      phase: Math.random() * 6,
      stumble: 0,
      stumbleTimer: 1 + Math.random() * 4,
      yaw: 0,
      lastGround: 0,
      lean: 0
    };
    g.position.set(lane * 0.5, 0.1, startZ + 0.5 + (i % 3) * 0.7);
    bots.push(bot);
  }

  const global = { bots, playerProgress: 0 };

  global.update = (dt, t, player, racing) => {
    const pProgress = Math.max(0, Math.min(1, (startZ - player.pos.z) / totalDistance));
    global.playerProgress = pProgress;
    for (const b of bots) {
      if (racing) {
        b.t = (b.t || 0) + dt;
        const tt = Math.min(1, b.t / b.finishTime);
        // stumbles cost time but bots keep moving
        b.progress = tt;
        if (b.t >= b.finishTime) b.finished = true;
      }
      const z = startZ - b.progress * totalDistance;
      b.z = z;
      let x = b.laneOffset;
      if (racing) {
        x += Math.sin(t * 0.8 + b.phase) * 0.7;
      }
      // squash toward centre at the finish
      if (b.progress > 0.94) x *= Math.max(0.15, (1 - b.progress) / 0.06);

      const ground = course.railGround(z, x);
      let groundTop = ground === null ? null : ground;
      if (groundTop !== null) {
        b.lastGround = groundTop;
        // jump when the next sample ahead has no floor
        const ahead = course.railGround(z - 1.6, x);
        const gapAhead = ahead === null;
        if (!gapAhead) {
          b.y = groundTop;
          b.rig.setPose('run', t, 0.85, 0.7);
        } else {
          b.y = groundTop + 0.8 + Math.abs(Math.sin(t * 6 + b.phase)) * 0.5;
          b.rig.setPose('jump', t, 0.6, 0.7);
        }
      } else {
        b.y = Math.max(b.lastGround + 0.9, b.y - dt * 0.4);
        b.rig.setPose('jump', t, 0.4, 0.6);
      }

      // comedic stumbles
      b.stumbleTimer -= dt;
      if (b.stumbleTimer <= 0 && !b.finished && racing) {
        b.stumble = 0.55 + Math.random() * 0.5;
        b.stumbleTimer = 4 + Math.random() * 6;
        b.finishTime += 0.35 + Math.random() * 0.8;
      }
      if (b.stumble > 0) {
        b.stumble -= dt;
        b.rig.body.rotation.z = Math.sin(t * 25) * 0.35;
        b.rig.body.rotation.x = Math.sin(t * 19) * 0.2;
        b.y += Math.abs(Math.sin(t * 15)) * 0.15;
      } else {
        b.rig.body.rotation.z *= (1 - Math.min(1, dt * 8));
        b.rig.body.rotation.x *= (1 - Math.min(1, dt * 8));
      }

      b.group.position.set(x, b.y, z);
      b.group.rotation.y = Math.sin(t * 1.2 + b.phase) * 0.15;
      if (b.finished) {
        b.rig.setPose('celebrate', t + b.phase, 0, 0);
        b.group.position.y = b.y + Math.abs(Math.sin(t * 5)) * 0.12;
      }
      if (b.progress > 0.97) b.rig.root.visible = true;
    }

    // rank by progress (and finish time once done)
    const entries = [
      { id: 'player', progress: pProgress, finished: player.finished, time: player.finishTime || 999 },
      ...bots.map(b => ({ id: b.id, progress: b.progress, finished: b.finished, time: b.finishTime }))
    ];
    entries.sort((a, b) => {
      if (a.finished && b.finished) return a.time - b.time;
      if (a.finished) return -1;
      if (b.finished) return 1;
      return b.progress - a.progress;
    });
    const rank = entries.findIndex(e => e.id === 'player') + 1;
    bots.forEach((b, i) => { b.rank = entries.findIndex(e => e.id === b.id) + 1; });
    return { rank, total: entries.length };
  };

  global.reset = () => {
    for (const b of bots) {
      b.progress = 0;
      b.t = 0;
      b.finished = false;
      b.stumble = 0;
      b.group.position.set(b.laneOffset * 0.5, 0.1, startZ + 0.5);
      b.rig.root.visible = true;
    }
  };

  return global;
}

