222:     },
223: 
224:     startRoundFromSession() {
225:       const s = this.session;
226:       let round, arena, diff = s.difficulty, endlessLevel = 0, botsCount = 7;
227:       if (s.type === 'career') {
228:         const p = s.plan[s.index];
229:         round = p.round; arena = p.arena;
230:         botsCount = 6;
231:       } else if (s.type === 'championship') {
232:         const p = s.plan[s.index];
233:         round = p.round; arena = p.arena;
234:         diff = s.difficulty * (1 + s.index * 0.02);
235:         botsCount = 6;
236:       } else if (s.type === 'endless') {
237:         round = ENDLESS_PLAN_ROUNDS[s.level % 4];
238:         const arenas = Object.keys(ARENAS);
239:         if (s.arenaChoice === 'random') arena = arenas[(s.level * 3 + 1) % arenas.length];
240:         else arena = s.arenaChoice;
241:         diff = s.difficulty * (1 + s.level * 0.055);
242:         endlessLevel = s.level + 1;
243:         botsCount = 3;
244:       } else if (s.type === 'timeTrial') {
245:         round = s.round; arena = s.arena; botsCount = 0;
246:       } else {
247:         round = s.round; arena = s.arena; botsCount = 6;
248:       }
249:       this.buildRound({ round, arena, difficulty: diff, endlessLevel, botsCount });
250:     },
251: 
252:     buildRound({ round, arena, difficulty = 1, endlessLevel = 0, botsCount = 7 }) {
253:       const s = this.session;
254:       this.roundInfo = { round, arena, difficulty, endlessLevel };
255:       this.config.round = round;
256:       this.config.arena = arena;
257: 
258:       if (this.gameScene) {
259:         this.gameScene.clear();
260:       }
261:       const scene = new THREE.Scene();
262:       this.gameScene = scene;
263:       this.scene = scene;
264:       const theme = ARENAS[arena] || ARENAS.classic;
265: 
266:       const course = buildCourse({
267:         round, arena: theme, difficulty,
268:         seedExtra: `${Date.now() % 10000}-${s.level || 0}`,
269:         endlessLevel
270:       });
271:       this.course = course;
272:       scene.add(course.group);
273:       const env = createEnvironment(theme, course.length, this.lowGfx ? 'low' : 'high');
274:       scene.add(env.group);
275:       this.env = env;
276:       scene.background = new THREE.Color(theme.skyHorizon);
277:       scene.fog = new THREE.Fog(theme.fog, 80, 300);
278: 
279:       const character = getCharacter(s.characterId);
280:       const player = createPlayer(course, character, { costume: s.costume, accessory: s.accessory });
281:       this.player = player;
282:       this.splashesTotal = s.type === 'endless' ? (s.startSplashes || 0) : 0;
283:       player.splashes = this.splashesTotal;
284:       player.finishTime = undefined;
285:       this.bindPlayer(player);
286: 
287:       const opts = {};
288:       if (s.type === 'championship') {
289:         const comp = s.competitors[s.index % s.competitors.length];
290:         opts.chars = s.competitors.map(c => getCharacter(c.charId));
291:         opts.names = s.competitors.map(c => c.name);
292:       }
293:       this.bots = botsCount > 0 ? createBots(course, character.id, botsCount, opts) : null;
294:       this.totalRacers = 1 + (this.bots ? this.bots.bots.length : 0);
295:       this.rank = 1;
296:       this.lastRank = 1;
297: 
298:       this.raceTime = 0;
299:       this.countdownTime = 3.7;
300:       this.lastCountdownShown = 99;
301:       this.state = 'countdown';
302:       this.endAt = 0;
303:       this.endKind = null;
304:       this.shake = 0;
305:       this.effects.forEach(e => this.removeEffect(e));
306:       this.effects = [];
307:       input.setEnabled(false);
308: 
309:       let label = `ROUND ${ROUNDS[round].number}`;
310:       let name = ROUNDS[round].name;
311:       if (s.type === 'career') label = `ROUND ${s.index + 1} OF 4`;
312:       else if (s.type === 'championship') label = `ROUND ${s.index + 1} OF 6`;
313:       else if (s.type === 'endless') label = `ENDLESS ${s.level + 1}`;
314:       else if (s.type === 'timeTrial') label = 'TIME TRIAL';
315:       else if (s.type === 'quick') label = 'QUICK PLAY';
316: 
317:       this.roundLabel = label;
318:       this.roundName = name;
319:       this.ui.setupHUD({
320:         roundLabel: label,
321:         roundName: name,
322:         maxSplashes: 3,
323:         totalRacers: this.totalRacers
324:       });
325:       this.ui.show('hud');
326:       this.ui.hideAllMenus();
327:       this.ui.showPause(false);
328:       this.ui.feed(`${theme.name.toUpperCase()} · ${ROUNDS[round].lengthHint}`, '');
329: 
330:       this.camera.position.set(player.pos.x, player.pos.y + 4.1, player.pos.z + 8.3);
331:       this.cameraLook.set(player.pos.x, player.pos.y + 1.2, player.pos.z - 4.5);
332:       this.camera.lookAt(this.cameraLook);
333:       this.ui.countdown('READY');
334:       audio.crowd(0.8);
335:     },
336: 
337:     bindPlayer(player) {
338:       player.callbacks = {
339:         onSplash: (pos, count) => {
340:           this.splashesTotal += 1;
341:           player.splashes = this.splashesTotal;
342:           this.spawnSplash(pos);
343:           this.shake = 0.7;
344:           this.ui.splashFlash();
345:           this.ui.feed('SPLASH! Back to the checkpoint', 'bad');
346:           audio.splash();
347:           if (this.splashesTotal >= 3) {
348:             this.state = 'ending';
349:             this.endKind = 'splash';
350:             this.endAt = 1.45;
351:             input.setEnabled(false);
352:           }
353:         },
354:         onHit: (hit) => {
355:           this.shake = Math.min(1.2, 0.35 + (hit.power || 8) * 0.05);
356:           this.spawnPop(hit.label || 'BONK!', player.pos.clone().add(new THREE.Vector3(0, 2.2, 0)), '#ffd23f');
357:           this.ui.feed(hit.label || 'BONK!', 'bad');
358:           audio.hit();
359:         },
360:         onCheckpoint: (cp) => {
361:           this.ui.feed(`${cp.label} · RESPAWN SAVED`, 'good');
362:           this.ui.bonus(cp.label + '!');
363:           audio.checkpoint();
364:           this.spawnPop(cp.label, cp.respawn ? new THREE.Vector3(cp.respawn.x, cp.respawn.top + 3, cp.respawn.z) : player.pos.clone(), '#6bff9d');
365:         },
366:         onJump: () => { audio.jump(); },
367:         onLand: (force) => { if (force > 0.55) audio.land(force); },
368:         onDive: () => { audio.dive(); },
369:         onLaunch: () => { audio.launch(); this.ui.bonus('LAUNCH!'); this.shake = 0.15; },
370:         onRecover: () => { this.ui.feed('Recovered. Somehow.', ''); },
371:         onRespawn: () => {
372:           this.cameraLook.set(player.pos.x, 1.4, player.pos.z - 5);
373:         },
374:         onFinish: () => {
375:           if (this.state === 'ending' || this.state === 'results') return;
376:           player.finishTime = this.raceTime;
377:           this.state = 'ending';
378:           this.endKind = 'finish';
379:           this.endAt = 2.1;
380:           input.setEnabled(false);
381:           this.rank = this.computeRank();
382:           this.resultRank = this.rank;
383:           this.shake = 0.3;
384:           audio.finish();
385:           this.spawnConfetti(player.pos.clone().add(new THREE.Vector3(0, 2, 0)));
386:           this.ui.bonus('FINISH!');
387:           this.ui.feed('FINISH!', 'good');
388:           audio.crowd(1.4);
389:         }
390:       };
391:     },
392: 
393:     computeRank() {
394:       if (!this.bots) return 1;
395:       const playerProgress = Math.max(0, Math.min(1, (this.course.startZ - this.player.pos.z) / Math.abs(this.course.finishZ - this.course.startZ)));
396:       let rank = 1;
397:       for (const b of this.bots.bots) {
398:         if (b.progress > playerProgress + 0.0001) rank++;
399:       }
400:       return rank;
401:     },
402: 
403:     /* ============================================================
404:        MAIN LOOP
405:        ============================================================ */
406:     loop(now) {
407:       const raw = (now - (this.lastTime || now)) / 1000;
408:       this.lastTime = now;
409:       const dt = Math.min(0.05, raw || 0.016);
410:       this.elapsed += dt;
411:       if (input.consumePause()) this.togglePause();
412:       if (this.state === 'menu') {
413:         this.updateMenu(dt);
414:       } else if (this.state === 'paused') {
415:         // keep rendering the frozen scene
416:       } else {
417:         this.updateRun(dt);
418:       }
419:       this.updateEffects(dt);
420:       this.renderer.render(this.scene, this.camera);
421:       requestAnimationFrame(t => this.loop(t));
422:     },
423: 
424:     updateRun(dt) {
425:       const player = this.player;
426:       const course = this.course;
427:       if (!player || !course) return;
428:       this.env?.update(dt, this.elapsed);
429: 
430:       if (this.state === 'countdown') {
431:         this.countdownTime -= dt;
432:         const shown = Math.ceil(this.countdownTime);
433:         if (shown !== this.lastCountdownShown && this.countdownTime > 0) {
434:           this.lastCountdownShown = shown;
435:           if (shown > 0 && shown <= 3) {
436:             this.ui.countdown(String(shown));
437:             audio.countdown(1);
438:           }
439:         }
440:         if (this.countdownTime <= 0.35 && this.lastCountdownShown !== 0) {
441:           this.lastCountdownShown = 0;
442:           this.ui.countdown('GO!');
443:           audio.countdown(0);
444:           this.state = 'racing';
445:           this.raceTime = 0;
446:           input.setEnabled(true);
447:           this.ui.feed('GO! GO! GO!', 'good');
448:         }
449:         const idle = { forward: 0, strafe: 0, sprint: false, jumpPressed: false, divePressed: false };
450:         course.update(dt, this.elapsed, player);
451:         player.update(dt, idle, this.elapsed);
452:         if (this.bots) this.bots.update(dt, this.elapsed, player, false);
453:       } else if (this.state === 'racing') {
454:         this.raceTime += dt;
455:         if (this.raceTime > 300) {
456:           this.state = 'ending'; this.endKind = 'timeout'; this.endAt = 1.2; input.setEnabled(false);
457:         }
458:         course.update(dt, this.elapsed, player);
459:         const frameInput = {
460:           forward: input.forward,
461:           strafe: input.strafe,
462:           sprint: input.sprint,
463:           jumpPressed: input.consumeJump(),
464:           divePressed: input.consumeDive()
465:         };
466:         if (this.bots) this.bots.update(dt, this.elapsed, player, true);
467:         player.update(dt, frameInput, this.elapsed);
468:         this.rank = this.computeRank();
469:         this.rankCooldown = Math.max(0, this.rankCooldown - dt);
470:         if (this.bots && this.rank !== this.lastRank && this.rankCooldown <= 0 && this.raceTime > 2) {
471:           if (this.rank < this.lastRank && this.lastRank !== 99) this.ui.feed(`OVERTAKE! Now ${ordinal(this.rank)}`, 'good');
472:           else if (this.lastRank !== 99) this.ui.feed(`Dropped to ${ordinal(this.rank)}`, 'bad');
473:           this.lastRank = this.rank;
474:           this.rankCooldown = 1.5;
475:         }
476:         if (this.lastRank === 99) this.lastRank = this.rank;
477:         this.updateHUDState();
478:       } else if (this.state === 'ending') {
479:         this.endAt -= dt;
480:         course.update(dt, this.elapsed, player);
481:         const idle = { forward: 0, strafe: 0, sprint: false, jumpPressed: false, divePressed: false };
482:         if (this.bots) this.bots.update(dt, this.elapsed, player, this.endKind === 'finish');
483:         player.update(dt, idle, this.elapsed);
484:         this.updateHUDState();
485:         if (this.endAt <= 0) {
486:           this.finalizeRound(this.endKind === 'finish');
487:         }
488:       } else if (this.state === 'results') {
489:         // results screen; gentle world motion
490:         course.update(dt, this.elapsed, player);
491:       }
492: 
493:       this.updateCamera(dt);
494:     },
495: 
496:     updateHUDState() {
497:       const player = this.player;
498:       if (!player) return;
499:       const progress = Math.max(0, Math.min(1, (this.course.startZ - player.pos.z) / Math.abs(this.course.finishZ - this.course.startZ)));
500:       const cp = player.checkpoint;
501:       this.ui.updateHUD({
502:         time: this.raceTime + (this.session.type === 'timeTrial' ? this.splashesTotal * 2 : 0),
503:         progress,
504:         rank: this.bots ? this.rank : 1,
505:         totalRacers: this.totalRacers,
506:         splashes: this.splashesTotal,
507:         stamina: player.stamina,
508:         speed: player.speed,
509:         checkpoint: cp ? cp.label : 'START'
510:       });
511:     },
512: 
513:     updateCamera(dt) {
514:       if (!this.player) return;
515:       const p = this.player;
516:       const cam = this.camera;
517:       if (this.state === 'ending' && this.endKind === 'finish') {
518:         this.menu.orbit = (this.menu.orbit || 0) + dt * 0.6;
519:         const a = this.menu.orbit;
520:         const target = p.pos.clone().add(new THREE.Vector3(0, 1.3, 0));
521:         cam.position.lerp(new THREE.Vector3(target.x + Math.sin(a) * 6.4, target.y + 2.6, target.z + Math.cos(a) * 6.4), Math.min(1, dt * 4));
522:         this.cameraLook.lerp(target, Math.min(1, dt * 6));
523:         cam.lookAt(this.cameraLook);
524:         return;
525:       }
526:       const speedFactor = Math.min(1.5, p.speed / 9);
527:       const back = 7.2 + speedFactor * 1.2 + (this.state === 'countdown' ? 1.8 : 0);
528:       const height = 3.9 + speedFactor * 0.35;
529:       const desired = new THREE.Vector3(
530:         p.pos.x + p.vel.x * 0.16,
531:         p.pos.y + height,
532:         p.pos.z + back
533:       );
534:       desired.y = Math.max(desired.y, WATER_Y + (p.state === 'splash' ? 3.4 : 1.6));
535:       cam.position.lerp(desired, Math.min(1, dt * 5.2));
536:       const lookTarget = new THREE.Vector3(
537:         p.pos.x + p.vel.x * 0.3,
538:         p.pos.y + 1.35 + (p.grounded ? 0 : 0.3),
539:         p.pos.z - 6.5
540:       );
541:       this.cameraLook.lerp(lookTarget, Math.min(1, dt * 7));
542:       cam.lookAt(this.cameraLook);
543: 
544:       if (this.shake > 0.001) {
545:         this.shake *= Math.pow(0.0018, dt);
546:         const s = this.shake;
547:         cam.position.x += (Math.random() - 0.5) * s * 0.8;
548:         cam.position.y += (Math.random() - 0.5) * s * 0.6;
549:         cam.rotation.z += (Math.random() - 0.5) * s * 0.03;
550:       } else {
551:         this.shake = 0;
552:       }
553:     },
554: 
555:     /* ============================================================
556:        EFFECTS
557:        ============================================================ */
558:     spawnSplash(pos) {
559:       const scene = this.gameScene;
560:       const count = 34;
561:       const positions = new Float32Array(count * 3);
562:       const vels = [];
563:       for (let i = 0; i < count; i++) {
564:         positions[i * 3] = pos.x;
565:         positions[i * 3 + 1] = WATER_Y + 0.1;
566:         positions[i * 3 + 2] = pos.z;
567:         const a = Math.random() * Math.PI * 2;
568:         const r = 1.5 + Math.random() * 4;
569:         vels.push(new THREE.Vector3(Math.cos(a) * r, 5 + Math.random() * 8, Math.sin(a) * r));
570:       }
571:       const geo = new THREE.BufferGeometry();
572:       geo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
573:       const pts = new THREE.Points(geo, new THREE.PointsMaterial({ color: '#d8fbff', size: 0.36, transparent: true, opacity: 1, depthWrite: false }));
574:       scene.add(pts);
575:       const ring = new THREE.Mesh(
576:         new THREE.TorusGeometry(1, 0.16, 6, 24),
577:         new THREE.MeshBasicMaterial({ color: '#c9f7ff', transparent: true, opacity: 0.9, depthWrite: false })
578:       );
579:       ring.rotation.x = -Math.PI / 2;
580:       ring.position.set(pos.x, WATER_Y + 0.06, pos.z);
581:       scene.add(ring);
582:       this.effects.push({ type: 'splash', pts, ring, vels, t: 0, life: 1.15, positions });
583:     },
584: 
585:     spawnConfetti(pos) {
586:       const scene = this.gameScene;
587:       const count = 90;
588:       const positions = new Float32Array(count * 3);
589:       const colors = new Float32Array(count * 3);
590:       const vels = [];
591:       const palette = [new THREE.Color('#ffd23f'), new THREE.Color('#ff5b2b'), new THREE.Color('#2fc4ff'), new THREE.Color('#43e08a'), new THREE.Color('#ff5fa2')];
592:       for (let i = 0; i < count; i++) {
593:         positions[i * 3] = pos.x + (Math.random() - 0.5) * 3;
594:         positions[i * 3 + 1] = pos.y + 2 + Math.random() * 2;
595:         positions[i * 3 + 2] = pos.z + (Math.random() - 0.5) * 3;
596:         const col = palette[i % palette.length];
597:         colors[i * 3] = col.r; colors[i * 3 + 1] = col.g; colors[i * 3 + 2] = col.b;
598:         vels.push(new THREE.Vector3((Math.random() - 0.5) * 4, 3 + Math.random() * 7, (Math.random() - 0.5) * 4));
599:       }
600:       const geo = new THREE.BufferGeometry();
601:       geo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
602:       geo.setAttribute('color', new THREE.BufferAttribute(colors, 3));
603:       const pts = new THREE.Points(geo, new THREE.PointsMaterial({ size: 0.28, vertexColors: true, transparent: true, opacity: 1, depthWrite: false }));
604:       scene.add(pts);
605:       this.effects.push({ type: 'confetti', pts, vels, t: 0, life: 2.8, positions });
606:     },
607: 
608:     spawnPop(text, pos, color = '#ffd23f') {
609:       const c = document.createElement('canvas');
610:       c.width = 320; c.height = 128;
611:       const ctx = c.getContext('2d');
612:       ctx.font = 'bold 55px Outfit, sans-serif';
613:       ctx.textAlign = 'center';
614:       ctx.textBaseline = 'middle';
615:       ctx.lineWidth = 12; ctx.strokeStyle = '#0b2136';
616:       ctx.strokeText(text, 160, 64);
617:       ctx.fillStyle = color;
618:       ctx.fillText(text, 160, 64);
619:       const tex = new THREE.CanvasTexture(c);
620:       tex.colorSpace = THREE.SRGBColorSpace;
621:       const mat = new THREE.SpriteMaterial({ map: tex, transparent: true, depthWrite: false });
622:       const sprite = new THREE.Sprite(mat);
623:       sprite.position.copy(pos);
624:       sprite.scale.set(4.2, 1.7, 1);
625:       if (this.gameScene) this.gameScene.add(sprite);
626:       this.effects.push({ type: 'pop', sprite, t: 0, life: 1.15, vy: 1.6 });
627:     },
628: 
629:     updateEffects(dt) {
630:       for (let i = this.effects.length - 1; i >= 0; i--) {
631:         const e = this.effects[i];
632:         e.t += dt;
633:         const k = e.t / e.life;
634:         if (e.type === 'splash') {
635:           const arr = e.positions;
636:           for (let j = 0; j < e.vels.length; j++) {
637:             e.vels[j].y -= 26 * dt;
638:             arr[j * 3] += e.vels[j].x * dt;
639:             arr[j * 3 + 1] += e.vels[j].y * dt;
640:             arr[j * 3 + 2] += e.vels[j].z * dt;
641:           }
642:           e.pts.geometry.attributes.position.needsUpdate = true;
643:           e.pts.material.opacity = Math.max(0, 1 - k);
644:           e.ring.scale.setScalar(1 + k * 5.5);
645:           e.ring.material.opacity = Math.max(0, 0.9 * (1 - k));
646:         } else if (e.type === 'confetti') {
647:           const arr = e.positions;
648:           for (let j = 0; j < e.vels.length; j++) {
649:             e.vels[j].y -= 9 * dt;
650:             arr[j * 3] += e.vels[j].x * dt;
651:             arr[j * 3 + 1] += e.vels[j].y * dt;
652:             arr[j * 3 + 2] += e.vels[j].z * dt;
653:           }
654:           e.pts.geometry.attributes.position.needsUpdate = true;
655:           e.pts.material.opacity = Math.max(0, 1 - k * k);
656:         } else if (e.type === 'pop') {
657:           e.sprite.position.y += e.vy * dt;
658:           e.vy *= 0.96;
659:           e.sprite.material.opacity = Math.max(0, 1 - k);
660:         }
661:         if (e.t >= e.life) {
662:           this.removeEffect(e);
663:           this.effects.splice(i, 1);
664:         }
665:       }
666:     },
667: 
668:     removeEffect(e) {
669:       if (e.pts) {
670:         this.gameScene?.remove(e.pts);
671:         e.pts.geometry?.dispose();
672:         e.pts.material?.dispose();
673:       }
674:       if (e.ring) {
675:         this.gameScene?.remove(e.ring);
676:         e.ring.geometry?.dispose();
677:         e.ring.material?.dispose();
678:       }
679:       if (e.sprite) {
680:         this.gameScene?.remove(e.sprite);
681:         e.sprite.material?.map?.dispose();
682:         e.sprite.material?.dispose();
683:       }
684:     },
685: 
686:     /* ============================================================
687:        ROUND FINISH / RESULTS
688:        ============================================================ */
