136:       const spin = new THREE.Group();
137:       spin.position.set(x, top + 0.01, z);
138:       pg.add(spin);
139:       const stripeMat = toonMat(theme.platformTrim);
140:       for (let i = 0; i < 4; i++) {
141:         m(spin, G.box, stripeMat, [0, 0.02, 0], [w * 0.88, 0.04, 0.28]).rotation.y = (i / 4) * Math.PI;
142:       }
143:       const rim = new THREE.Mesh(new THREE.TorusGeometry(w / 2 - 0.1, 0.18, 6, 28), toonMat(trim));
144:       rim.rotation.x = Math.PI / 2; rim.position.set(x, top - 0.05, z);
145:       pg.add(rim);
146:       m(pg, G.cyl, toonMat('#30363f'), [x, top + 0.5, z], [0.8, 1.4, 0.8]);
147:       m(pg, G.cyl, toonMat(theme.accent), [x, top + 1.3, z], [1.1, 0.2, 1.1]);
148:       p.spinMesh = spin;
149:       return p;
150:     }
151: 
152:     const depthT = kind === 'beam' ? 1.3 : 2.6;
153:     const slab = new THREE.Mesh(new THREE.BoxGeometry(w, depthT, depth), topMat(color, trim, kind));
154:     slab.position.set(x, top - depthT / 2, z);
155:     pg.add(slab);
156:     // skirt
157:     const skirtH = kind === 'beam' ? 0.7 : 1.35;
158:     const skirt = new THREE.Mesh(
159:       new THREE.BoxGeometry(w - 0.25, skirtH, depth - 0.25),
160:       toonMat(sideColor)
161:     );
162:     skirt.position.set(x, top - depthT - skirtH / 2 + 0.05, z);
163:     pg.add(skirt);
164:     // edge trims
165:     const edgeMat = toonMat(trim);
166:     const edgeH = 0.13;
167:     const longZ = kind === 'beam';
168:     if (!longZ) {
169:       m(pg, G.box, edgeMat, [x - w / 2 + 0.16, top + 0.06, z], [0.34, edgeH, depth]);
170:       m(pg, G.box, edgeMat, [x + w / 2 - 0.16, top + 0.06, z], [0.34, edgeH, depth]);
171:     }
172:     m(pg, G.box, edgeMat, [x, top + 0.06, zBack - 0.18], [w, edgeH, 0.36]);
173:     m(pg, G.box, edgeMat, [x, top + 0.06, zFront + 0.18], [w, edgeH, 0.36]);
174:     // corner floaters
175:     const cornerMat = toonMat(theme.accent);
176:     if (kind !== 'beam') {
177:       [[-1, -1], [1, -1], [-1, 1], [1, 1]].forEach(([sx, sz]) => {
178:         m(pg, G.sphere, cornerMat, [x + sx * (w / 2 - 0.5), top - 0.1, z + sz * (depth / 2 - 0.5)], [0.55, 0.45, 0.55]);
179:       });
180:     }
181:     if (slippery) {
182:       const ice = new THREE.Mesh(new THREE.BoxGeometry(w - 0.5, 0.06, depth - 0.3), new THREE.MeshToonMaterial({
183:         color: '#bdefff', transparent: true, opacity: 0.35
184:       }));
185:       ice.position.set(x, top + 0.045, z);
186:       pg.add(ice);
187:     }
