189:     if (kind === 'flat' && depth > 8) {
190:       [[-1, -1], [1, -1], [-1, 1], [1, 1]].forEach(([sx, sz]) => {
191:         m(pg, G.cyl, toonMat(sideColor), [x + sx * (w / 2 - 1), top - 2.1, z + sz * (depth / 2 - 1)], [0.35, 1.7, 0.35]);
192:       });
193:     }
194:     return p;
