() => {
  window.__qa = {
    async run(maxMs = 90000) {
      const g = window.__wipeout.game;
      const key = (code, down) => {
        window.dispatchEvent(new KeyboardEvent(down ? 'keydown' : 'keyup', { code, bubbles: true }));
      };
      const tap = (code) => { key(code, true); setTimeout(() => key(code, false), 110); };
      for (let i = 0; i < 80 && g.state !== 'racing'; i++) await new Promise(r => setTimeout(r, 250));
      key('KeyW', true);
      const t0 = performance.now();
      let lastJump = -9;
      window.__trace = [];
      while (performance.now() - t0 < maxMs) {
        await new Promise(r => setTimeout(r, 120));
        const p = g.player;
        if (!p || g.state !== 'racing') break;
        const plats = g.course.platforms;
        const cur = plats.filter(pl => pl.active && pl.contains(p.pos.x, p.pos.z)).sort((a, b) => b.top - a.top)[0];
        let target = cur;
        if (cur) {
          const next = plats.filter(pl => pl.active && pl.id !== cur.id && pl.zBack <= cur.zBack - 0.4).sort((a, b) => b.zBack - a.zBack)[0];
          if (next && p.pos.z - cur.zFront < 5) target = next;
        }
        if (target) {
          const dx = target.x - p.pos.x;
          if (Math.abs(dx) > 0.6) {
            key(dx > 0 ? 'KeyD' : 'KeyA', true);
            key(dx > 0 ? 'KeyA' : 'KeyD', false);
          } else {
            key('KeyA', false);
            key('KeyD', false);
          }
        }
        if (p.grounded && g.raceTime - lastJump > 0.45) {
          let nearEdge = false;
          if (cur && cur.kind === 'disc') nearEdge = Math.hypot(p.pos.x - cur.x, p.pos.z - cur.z) > cur.w / 2 - 2.0;
          else if (cur) { const d = p.pos.z - cur.zFront; nearEdge = d < 1.9 && d > -0.6; }
          if (nearEdge) { tap('Space'); lastJump = g.raceTime; }
        }
        window.__trace.push({ t: +g.raceTime.toFixed(1), z: +p.pos.z.toFixed(1), x: +p.pos.x.toFixed(1), y: +p.pos.y.toFixed(1), cp: p.checkpointIndex, ps: p.state });
      }
      key('KeyW', false); key('KeyA', false); key('KeyD', false);
      await new Promise(r => setTimeout(r, 3000));
      const tr = window.__trace;
      return {
        state: g.state, z: +g.player.pos.z.toFixed(1), finished: g.player.finished,
        splashes: g.splashesTotal, rank: g.rank, time: +g.raceTime.toFixed(1),
        trace: tr.filter((v, i) => i % 8 === 0)
      };
    }
  };
  return 'ready';
}

