350:   // collapsing section uses individual tiles
351:   function addCollapseSection(depth = 22, width = 13) {
352:     const gap = 2.2;
353:     const zBack = cursor - gap;
354:     const zFront = zBack - depth;
355:     const cols = 4, rows = 4;
356:     const tw = width / cols - 0.18, td = depth / rows - 0.18;
357:     const pg = new THREE.Group();
358:     group.add(pg);
359:     for (let r = 0; r < rows; r++) {
360:       for (let c = 0; c < cols; c++) {
361:         const tx = -width / 2 + tw / 2 + c * (tw + 0.18);
362:         const tz = zBack - td / 2 - r * (td + 0.18);
363:         const tile = addPlatform({
364:           x: tx, zBack: tz + td / 2, depth: td, w: tw, top: 0,
365:           kind: 'tile', color: (r + c) % 2 ? theme.platform : theme.platformSide,
366:           edge: 0.01
367:         });
368:         // replace visual with a chunkier tile
369:         if (tile.mesh) {
370:           tile.mesh.position.y = 0;
371:           tile.tileMesh = tile.mesh;
372:         }
373:         tile.collapse = { period: 3.8, offset: r * 0.55 + c * 0.2 + rand() * 0.1, off: 0.8, active: true };
374:         tile.active = true;
375:         tile.baseTop = 0;
376:       }
377:     }
378:     cursor = zFront;
379:     // safety rails on edges
380:     return { zBack, zFront };
381:   }
