531:   const course = {
532:     round, arena: theme, group, platforms, obstacles, pads, checkpoints, finish, finishZ,
533:     startZ: 8, startX: 0, top: 0, length, parTime,
534:     startPlatform: start,
535:     checkpointsSorted: checkpoints.slice().sort((a, b) => a.index - b.index),
