537:     groundAt(x, z, maxY = 999) {
538:       let best = null;
539:       for (let i = 0; i < platforms.length; i++) {
540:         const p = platforms[i];
541:         if (!p.active) continue;
542:         if (!p.contains(x, z)) continue;
543:         const top = p.topAt(x, z);
544:         if (top <= maxY + 0.06 && (!best || top > best.top)) best = { platform: p, top };
545:       }
546:       return best;
547:     },
