549:     update(dt, t, player) {
550:       for (let i = 0; i < obstacles.length; i++) obstacles[i].update(dt, t);
551:       for (let i = 0; i < platforms.length; i++) {
552:         const p = platforms[i];
553:         if (p.kind === 'disc' && p.spinMesh) p.spinMesh.rotation.y = t * p.spinRate;
554:         if (p.collapse) {
555:           const c = p.collapse;
556:           const phase = (t + c.offset) % c.period;
557:           const wasActive = p.active;
558:           const offStart = c.period - c.off;
559:           p.active = phase < offStart;
560:           if (p.mesh) {
561:             const targetY = p.active ? 0 : -1.4;
562:             p.mesh.position.y += (targetY - p.mesh.position.y) * Math.min(1, dt * 12);
563:             if (p.active && !wasActive) p.mesh.position.y = 0;
564:             // warning shake
565:             p.mesh.rotation.z = (!p.active ? 0 : (phase > offStart - 0.55 ? Math.sin(t * 45) * 0.035 : 0));
566:           }
567:         }
568:       }
569:       // start lights go green after countdown
570:       if (start.lights) {
571:         start.lights.children.forEach((l, i) => {
572:           const on = t > 0.2 + i * 0.7;
573:           l.material = toonMat(on ? '#6bff9d' : '#ff4d5e', { emissive: on ? '#38ff7d' : '#ff4d5e', emissiveIntensity: 1.1 });
574:         });
575:       }
576:     },
