65:     ctx.beginPath();
66:     ctx.moveTo(64, 22); ctx.lineTo(84, 62); ctx.lineTo(72, 62); ctx.lineTo(72, 104);
67:     ctx.lineTo(56, 104); ctx.lineTo(56, 62); ctx.lineTo(44, 62); ctx.closePath(); ctx.fill();
68:     ctx.globalAlpha = 1;
69:   }
70:   const tex = new THREE.CanvasTexture(c);
71:   tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
72:   tex.colorSpace = THREE.SRGBColorSpace;
73:   topTextures.set(key, tex);
74:   return tex;
75: }
76: 
77: export function buildCourse({ round, arena, difficulty = 1, seedExtra = '', endlessLevel = 0 }) {
78:   const group = new THREE.Group();
79:   const platforms = [];
80:   const obstacles = [];
81:   const pads = [];
82:   const checkpoints = [];
83:   const rand = rng(hashSeed(round, arena.id, seedExtra + endlessLevel));
84:   const theme = arena;
85: 
86:   let cursor = -2; // front edge of the last platform
87:   let platformId = 0;
88: 
89:   const topMat = (color, trim, kind) => {
90:     const tex = platformTexture(color, trim, kind);
91:     const t = tex.clone();
92:     t.needsUpdate = true;
93:     t.wrapS = t.wrapT = THREE.RepeatWrapping;
94:     t.repeat.set(1.5, 1.5);
95:     return new THREE.MeshToonMaterial({ map: t });
96:   };
97: 
98:   function addPlatform(opt) {
99:     const {
100:       x = 0, zBack, depth, w = 13, top = 0, kind = 'flat',
101:       color = theme.platform, sideColor = theme.platformSide, trim = theme.platformTrim,
102:       slippery = false, hole = false
103:     } = opt;
104:     const zFront = zBack - depth;
105:     const z = (zBack + zFront) / 2;
106:     const p = {
107:       id: platformId++, kind, x, z, w, d: depth, top, zBack, zFront,
108:       slippery, active: true, slopeX: opt.slopeX || 0, slopeZ: opt.slopeZ || 0,
109:       conveyor: opt.conveyor || null, spinRate: opt.spinRate || 0, mesh: null,
110:       collapse: opt.collapse || null, beam: kind === 'beam',
111:       topAt(px, pz) { return top + this.slopeX * (px - this.x) + this.slopeZ * (pz - this.z); },
112:       contains(px, pz) {
113:         if (kind === 'disc') return Math.hypot(px - x, pz - z) <= w / 2 + (opt.edge ?? 0.06);
114:         return Math.abs(px - x) <= w / 2 + (opt.edge ?? 0.06) && px > -900 &&
115:           pz <= zBack + (opt.edge ?? 0.06) && pz >= zFront - (opt.edge ?? 0.06);
116:       }
117:     };
118:     platforms.push(p);
119:     if (hole) return p;
120:     const pg = new THREE.Group();
121:     group.add(pg);
122:     p.mesh = pg;
123: 
124:     if (kind === 'tile') {
125:       const slab = new THREE.Mesh(new THREE.BoxGeometry(w, 0.7, depth), topMat(color, trim, 'tile'));
126:       slab.position.set(x, top - 0.35, z);
127:       pg.add(slab);
128:       return p;
129:     }
130: 
131:     if (kind === 'disc') {
132:       const disc = new THREE.Mesh(new THREE.CylinderGeometry(w / 2, w / 2 - 0.35, 1.2, 26), topMat(color, trim, 'disc'));
133:       disc.position.set(x, top - 0.6, z);
134:       pg.add(disc);
135:       // rotating top plate marks
136:       const spin = new THREE.Group();
137:       spin.position.set(x, top + 0.01, z);
138:       pg.add(spin);
139:       const stripeMat = toonMat(theme.platformTrim);
140:       for (let i = 0; i < 4; i++) {
141:         m(spin, G.box, stripeMat, [0, 0.02, 0], [w * 0.88, 0.04, 0.28]).rotation.y = (i / 4) * Math.PI;
142:       }
143:       const rim = new THREE.Mesh(new THREE.TorusGeometry(w / 2 - 0.1, 0.18, 6, 28), toonMat(trim));
144:       rim.rotation.x = Math.PI / 2; rim.position.set(x, top - 0.05, z);
145:       pg.add(rim);
146:       m(pg, G.cyl, toonMat('#30363f'), [x, top + 0.5, z], [0.8, 1.4, 0.8]);
147:       m(pg, G.cyl, toonMat(theme.accent), [x, top + 1.3, z], [1.1, 0.2, 1.1]);
148:       p.spinMesh = spin;
149:       return p;
150:     }
151: 
152:     const depthT = kind === 'beam' ? 1.3 : 2.6;
153:     const slab = new THREE.Mesh(new THREE.BoxGeometry(w, depthT, depth), topMat(color, trim, kind));
154:     slab.position.set(x, top - depthT / 2, z);
155:     pg.add(slab);
156:     // skirt
157:     const skirtH = kind === 'beam' ? 0.7 : 1.35;
158:     const skirt = new THREE.Mesh(
159:       new THREE.BoxGeometry(w - 0.25, skirtH, depth - 0.25),
160:       toonMat(sideColor)
161:     );
162:     skirt.position.set(x, top - depthT - skirtH / 2 + 0.05, z);
163:     pg.add(skirt);
164:     // edge trims
165:     const edgeMat = toonMat(trim);
166:     const edgeH = 0.13;
167:     const longZ = kind === 'beam';
168:     if (!longZ) {
169:       m(pg, G.box, edgeMat, [x - w / 2 + 0.16, top + 0.06, z], [0.34, edgeH, depth]);
170:       m(pg, G.box, edgeMat, [x + w / 2 - 0.16, top + 0.06, z], [0.34, edgeH, depth]);
171:     }
172:     m(pg, G.box, edgeMat, [x, top + 0.06, zBack - 0.18], [w, edgeH, 0.36]);
173:     m(pg, G.box, edgeMat, [x, top + 0.06, zFront + 0.18], [w, edgeH, 0.36]);
174:     // corner floaters
175:     const cornerMat = toonMat(theme.accent);
176:     if (kind !== 'beam') {
177:       [[-1, -1], [1, -1], [-1, 1], [1, 1]].forEach(([sx, sz]) => {
178:         m(pg, G.sphere, cornerMat, [x + sx * (w / 2 - 0.5), top - 0.1, z + sz * (depth / 2 - 0.5)], [0.55, 0.45, 0.55]);
179:       });
180:     }
181:     if (slippery) {
182:       const ice = new THREE.Mesh(new THREE.BoxGeometry(w - 0.5, 0.06, depth - 0.3), new THREE.MeshToonMaterial({
183:         color: '#bdefff', transparent: true, opacity: 0.35
184:       }));
185:       ice.position.set(x, top + 0.045, z);
186:       pg.add(ice);
187:     }
188:     // support pylons (only for wide platforms)
189:     if (kind === 'flat' && depth > 8) {
190:       [[-1, -1], [1, -1], [-1, 1], [1, 1]].forEach(([sx, sz]) => {
191:         m(pg, G.cyl, toonMat(sideColor), [x + sx * (w / 2 - 1), top - 2.1, z + sz * (depth / 2 - 1)], [0.35, 1.7, 0.35]);
192:       });
193:     }
194:     return p;
195:   }
196: 
197:   function nextSection(depth, opt = {}) {
198:     // Keep the opening route connected to the start platform; later gaps are
199:     // intentional jumps sized to clear comfortably with a running jump.
200:     const gap = opt.gap ?? (cursor === -2 ? 0 : 2.2);
201:     const zBack = cursor - gap;
202:     const p = addPlatform({ ...opt, zBack, depth });
203:     cursor = zBack - depth;
204:     return p;
205:   }
206: 
207:   function addCheckpoint(p, label, index) {
208:     const z = p.z + p.d / 2 - 2.2;
209:     // The start gate would sit between the chase camera and the player during
210:     // the countdown, filling the screen. The start gantry already marks it.
211:     if (index > 0) {
212:       const gate = createCheckpointGate(theme, z, index);
213:       group.add(gate);
214:     }
215:     checkpoints.push({
216:       index, label, z, platform: p,
217:       respawn: { x: p.x, z: z - 0.8, top: p.topAt(p.x, z) }
218:     });
219:   }
220: 
221:   function addObs(type, opt) {
222:     const o = createObstacle(type, opt, theme);
223:     group.add(o.group);
224:     obstacles.push(o);
225:     if (type === 'launch') pads.push(o);
226:     return o;
227:   }
228: 
229:   function decorateSection(p, opts = {}) {
230:     // hazard rail lights along the sides
231:     const lightMat = toonMat(theme.accent, { emissive: theme.accent, emissiveIntensity: 0.8 });
232:     const n = Math.max(1, Math.floor(p.d / 7));
233:     for (let i = 0; i < n; i++) {
234:       const zz = p.zBack - (i + 0.5) * (p.d / n);
235:       [-1, 1].forEach(s => {
236:         if (p.kind === 'beam') return;
237:         m(group, G.sphere, lightMat, [p.x + s * (p.w / 2 - 0.4), p.top + 0.6, zz], [0.11, 0.11, 0.11]);
238:       });
239:     }
240:     if (opts.arch) {
241:       const archMat = toonMat(theme.accent);
242:       const arch = new THREE.Mesh(new THREE.TorusGeometry(p.w / 2 + 1.2, 0.35, 7, 24, Math.PI), archMat);
243:       arch.position.set(p.x, p.top + 2.4, p.z + p.d / 2 - 1);
244:       group.add(arch);
245:       const sign = m(group, new THREE.PlaneGeometry(6, 1.4), toonMat(theme.accent2), [p.x, p.top + 5.4, p.z + p.d / 2 - 1], [1, 1, 1]);
246:       sign.rotation.y = 0;
247:     }
248:   }
249: 
250:   // =========================================================================
251:   // START
252:   // =========================================================================
253:   const start = addPlatform({ zBack: 14, depth: 16, w: 16, top: 0, kind: 'start' });
254:   cursor = -2;
255:   start.isStart = true;
256:   // start gantry
257:   {
258:     const g = new THREE.Group();
259:     group.add(g);
260:     const postMat = toonMat(theme.platformSide);
261:     [-1, 1].forEach(s => {
262:       m(g, G.box, postMat, [s * 6.2, 3.6, 1.0], [0.7, 7.2, 0.7]);
263:       m(g, G.sphere, toonMat(theme.accent, { emissive: theme.accent, emissiveIntensity: 0.6 }), [s * 6.2, 7.2, 1.0], [0.5, 0.5, 0.5]);
264:     });
265:     m(g, G.box, toonMat(theme.accent), [0, 7.35, 1.0], [12.4, 0.55, 0.6]);
266:     const startLights = new THREE.Group();
267:     for (let i = 0; i < 3; i++) {
268:       const light = m(startLights, G.sphere, toonMat('#ff4d5e', { emissive: '#ff4d5e', emissiveIntensity: 1.2 }), [(i - 1) * 1.5, 7.65, 0.85], [0.4, 0.4, 0.4]);
269:       light.userData.startLight = i;
270:     }
271:     g.add(startLights);
272:     start.lights = startLights;
273:   }
274:   // =========================================================================
275:   // SECTION BUILDERS
276:   // =========================================================================
277:   const builders = {
278:     balls(p) {
279:       const laneXs = p.w > 13 ? [-4.2, 0, 4.2] : [-3.2, 3.2];
280:       const count = difficulty > 1.12 ? 3 : 2;
281:       for (let i = 0; i < count; i++) {
282:         addObs('ball', {
283:           x: laneXs[i % laneXs.length] + (rand() - 0.5) * 0.8,
284:           top: p.top, zFar: p.zFront + 1.5, span: p.d - 2,
285:           speed: 4.0 + rand() * 1.2 + difficulty * 0.3,
286:           phase: rand(), radius: 1.75,
287:           bounceHeight: 1.0
288:         });
289:       }
290:       decorateSection(p);
291:     },
292:     sweepers(p, n = 1) {
293:       for (let i = 0; i < n; i++) {
294:         const zz = p.zBack - p.d * (i + 0.5) / n;
295:         addObs('sweeper', {
296:           x: 0, z: zz, top: p.top, reach: Math.max(2.2, Math.min(5.2, p.w / 2 - 2.0)),
297:           speed: (1.35 + rand() * 0.35) * (difficulty > 1.15 ? 1.2 : 1),
298:           dir: i % 2 ? -1 : 1, phase: rand() * 2
299:         });
300:       }
301:       decorateSection(p);
302:     },
303:     hammers(p, n = 2) {
304:       for (let i = 0; i < n; i++) {
305:         const zz = p.zBack - p.d * (i + 0.5) / n;
306:         addObs('hammer', {
307:           x: p.x, z: zz, top: p.top, pivotH: 5.2, arm: p.kind === 'beam' ? 3.6 : 3.9,
308:           amp: 1.15, speed: 1.25 + rand() * 0.3, phase: rand() * 3
309:         });
310:       }
311:       decorateSection(p);
312:     },
313:     punches(p, n = 2) {
314:       for (let i = 0; i < n; i++) {
315:         const zz = p.zBack - p.d * (i + 0.5) / n;
316:         const side = i % 2 ? 1 : -1;
317:         addObs('punch', {
318:           x: p.x, z: zz, top: p.top, side, mountX: p.w / 2 + 0.3,
319:           period: 2.3 + rand() * 0.4, extend: p.w * 0.36, phase: rand()
320:         });
321:       }
322:       decorateSection(p);
323:     },
324:     walls(p, n = 2) {
325:       for (let i = 0; i < n; i++) {
326:         const zz = p.zBack - p.d * (i + 0.5) / n;
327:         addObs('wall', {
328:           x: p.x, z: zz, top: p.top, w: 3.5, amp: Math.max(2.6, p.w / 2 - 2.6),
329:           speed: 0.95 + rand() * 0.3, phase: rand() * 2, track: p.w - 1
330:         });
331:       }
332:       decorateSection(p);
333:     },
334:     rollers(p, n = 2) {
335:       for (let i = 0; i < n; i++) {
336:         addObs('roller', {
337:           x: (i - (n - 1) / 2) * 3.2 + p.x, top: p.top, zFar: p.zFront + 1,
338:           span: p.d + 3, radius: 0.55, len: 4.6, speed: 4.5 + rand() * 1.5,
339:           phase: rand()
340:         });
341:       }
342:       decorateSection(p);
343:     },
344:     launch(p) {
345:       addObs('launch', { x: p.x, z: p.z + 1, top: p.top, power: 16, forward: 6 });
346:       decorateSection(p);
347:     }
348:   };
349: 
350:   // collapsing section uses individual tiles
351:   function addCollapseSection(depth = 22, width = 13) {
352:     const gap = 2.2;
353:     const zBack = cursor - gap;
354:     const zFront = zBack - depth;
355:     const cols = 4, rows = 4;
356:     const tw = width / cols - 0.18, td = depth / rows - 0.18;
357:     const pg = new THREE.Group();
358:     group.add(pg);
359:     for (let r = 0; r < rows; r++) {
360:       for (let c = 0; c < cols; c++) {
361:         const tx = -width / 2 + tw / 2 + c * (tw + 0.18);
362:         const tz = zBack - td / 2 - r * (td + 0.18);
363:         const tile = addPlatform({
364:           x: tx, zBack: tz + td / 2, depth: td, w: tw, top: 0,
365:           kind: 'tile', color: (r + c) % 2 ? theme.platform : theme.platformSide,
366:           edge: 0.01
367:         });
368:         // replace visual with a chunkier tile
369:         if (tile.mesh) {
370:           tile.mesh.position.y = 0;
371:           tile.tileMesh = tile.mesh;
372:         }
373:         tile.collapse = { period: 3.8, offset: r * 0.55 + c * 0.2 + rand() * 0.1, off: 0.8, active: true };
374:         tile.active = true;
375:         tile.baseTop = 0;
376:       }
377:     }
378:     cursor = zFront;
379:     // safety rails on edges
380:     return { zBack, zFront };
381:   }
382: 
383:   function addDiscSection(count = 2) {
384:     const zBack = cursor - 3;
385:     let zz = zBack;
386:     for (let i = 0; i < count; i++) {
387:       const p = addPlatform({
388:         x: (i - (count - 1) / 2) * 5.4 + (rand() - 0.5) * 1.2,
389:         zBack: zz, depth: 8.5, w: 8.6, top: 0, kind: 'disc',
390:         spinRate: (i % 2 ? -1 : 1) * (1.0 + rand() * 0.5)
391:       });
392:       p.d = 8.5;
393:       zz = zz - 8.5 - 3.0;
394:     }
395:     cursor = zz + 3.0;
396:     return zz;
397:   }
