399:   // =========================================================================
400:   // ROUND LAYOUTS
401:   // =========================================================================
402:   const isEndless = endlessLevel > 0;
403:   const diff = difficulty * (1 + endlessLevel * 0.06);
404: 
405:   if (round === 'qualifier') {
406:     addCheckpoint(start, 'START', 0);
407:     const p1 = nextSection(24, { w: 14 });
408:     builders.balls(p1);
409:     const p2 = nextSection(20, { w: 14, slippery: true, conveyor: { x: (rand() > 0.5 ? 1 : -1) * 1.5 } });
410:     builders.rollers(p2, 2);
411:     addCheckpoint(p2, 'CHECKPOINT 1', 1);
412:     const p3 = nextSection(18, { w: 3.6, kind: 'beam', color: theme.platformSide });
413:     builders.hammers(p3, 1);
414:     const p4 = nextSection(20, { w: 14 });
415:     builders.walls(p4, 2);
416:     const p5 = nextSection(10, { w: 12 });
417:     builders.launch(p5);
418:     addCheckpoint(p5, 'CHECKPOINT 2', 2);
419: 
420:   } else if (round === 'sweeper') {
421:     addCheckpoint(start, 'START', 0);
422:     const p1 = nextSection(24, { w: 15 });
423:     builders.sweepers(p1, 2);
424:     const p2 = nextSection(15, { w: 14 });
425:     builders.punches(p2, 1);
426:     addCheckpoint(p2, 'CHECKPOINT 1', 1);
427:     const p3 = addPlatform({ zBack: cursor - 3.0, depth: 7, w: 6.8, x: -2.4 });
428:     cursor = p3.zFront;
429:     const p4 = addPlatform({ zBack: cursor - 3.2, depth: 7, w: 6.8, x: 2.6 });
430:     cursor = p4.zFront;
431:     const p5 = nextSection(22, { w: 15 });
432:     builders.sweepers(p5, 2);
433:     addCheckpoint(p5, 'CHECKPOINT 2', 2);
434:     const p6 = nextSection(18, { w: 3.8, kind: 'beam', color: theme.platformSide });
435:     builders.hammers(p6, 1);
436:     const p7 = nextSection(16, { w: 14 });
437:     builders.walls(p7, 2);
438:     const p8 = nextSection(9, { w: 12 });
439:     builders.launch(p8);
440: 
441:   } else if (round === 'dizzy') {
442:     addCheckpoint(start, 'START', 0);
443:     addDiscSection(2);
444:     const p1 = nextSection(24, { w: 15 });
445:     builders.sweepers(p1, 1);
446:     builders.hammers(p1, 1);
447:     addCheckpoint(p1, 'CHECKPOINT 1', 1);
448:     const p2 = nextSection(22, { w: 13, slippery: true, conveyor: { x: -1.9 } });
449:     builders.rollers(p2, 2);
450:     addCheckpoint(p2, 'CHECKPOINT 2', 2);
451:     addCollapseSection(22, 13);
452:     addDiscSection(2);
453:     const p3 = nextSection(20, { w: 3.8, kind: 'beam', color: theme.platformSide });
454:     builders.hammers(p3, 2);
455:     const p4 = nextSection(20, { w: 14 });
456:     builders.punches(p4, 2);
457:     addCheckpoint(p4, 'CHECKPOINT 3', 3);
458:     const p5 = nextSection(9, { w: 12 });
459:     builders.launch(p5);
460: 
461:   } else { // WIPEOUT ZONE - everything
462:     addCheckpoint(start, 'START', 0);
463:     const p1 = nextSection(22, { w: 14 });
464:     builders.balls(p1);
465:     builders.sweepers(p1, 1);
466:     const p2 = nextSection(24, { w: 15 });
467:     builders.sweepers(p2, 3);
468:     builders.punches(p2, 1);
469:     addCheckpoint(p2, 'CHECKPOINT 1', 1);
470:     const p3 = nextSection(22, { w: 14, slippery: true, conveyor: { x: (rand() > 0.5 ? -1 : 1) * 2.0 } });
471:     builders.rollers(p3, 3);
472:     builders.walls(p3, 2);
473:     addCheckpoint(p3, 'CHECKPOINT 2', 2);
474:     addCollapseSection(22, 13);
475:     const p4 = nextSection(22, { w: 14 });
476:     builders.punches(p4, 3);
477:     builders.balls(p4);
478:     addCheckpoint(p4, 'CHECKPOINT 3', 3);
479:     addDiscSection(3);
480:     const p5 = nextSection(22, { w: 15 });
481:     builders.sweepers(p5, 2);
482:     builders.hammers(p5, 2);
483:     addCheckpoint(p5, 'CHECKPOINT 4', 4);
484:     const p6 = nextSection(20, { w: 4.0, kind: 'beam', color: theme.platformSide });
485:     builders.hammers(p6, 2);
486:     const p7 = nextSection(20, { w: 14 });
487:     builders.walls(p7, 3);
488:     const p8 = nextSection(20, { w: 14, slippery: true, conveyor: { x: (rand() > 0.5 ? -1 : 1) * 2.2 } });
489:     builders.rollers(p8, 2);
490:     builders.punches(p8, 2);
491:     addCheckpoint(p8, 'CHECKPOINT 5', 5);
492:     const p9 = nextSection(10, { w: 12 });
493:     builders.launch(p9);
494:     addCheckpoint(p9, 'FINAL CHECKPOINT', 6);
495:   }
496: 
497:   // =========================================================================
498:   // FINISH PLATFORM + ARCH
499:   // =========================================================================
500:   const finish = addPlatform({
501:     zBack: cursor - 2.6, depth: 20, w: 20, kind: 'start',
502:     color: theme.platform, trim: theme.accent
503:   });
504:   const finishZ = finish.zBack - 1.5;
505:   finish.isFinish = true;
506:   {
507:     const g = new THREE.Group();
508:     group.add(g);
509:     const postMat = toonMat(theme.platformSide);
510:     [-1, 1].forEach(s => {
511:       m(g, G.box, postMat, [s * 9.4, 3, finish.zBack - 4], [0.9, 6, 0.9]);
512:       m(g, G.sphere, toonMat(theme.accent, { emissive: theme.accent, emissiveIntensity: 0.7 }), [s * 9.4, 6.2, finish.zBack - 4], [0.55, 0.55, 0.55]);
513:     });
514:     m(g, G.box, toonMat(theme.accent), [0, 6.7, finish.zBack - 4], [19.5, 1.2, 0.8]);
515:     // checkered finish line
516:     const checker = document.createElement('canvas');
517:     checker.width = 256; checker.height = 64;
518:     const cx = checker.getContext('2d');
519:     for (let yy = 0; yy < 4; yy++) for (let xx = 0; xx < 16; xx++) {
520:       cx.fillStyle = (xx + yy) % 2 ? '#ffffff' : '#151b26';
521:       cx.fillRect(xx * 16, yy * 16, 16, 16);
522:     }
