340: function roller(opt, arena) {
341:   const group = new THREE.Group();
342:   group.position.set(opt.x || 0, opt.top + (opt.radius || 0.55), opt.z || 0);
343:   const r = opt.radius || 0.55;
344:   const len = opt.len || 5.2;
345:   const bar = new THREE.Mesh(G.cylAxisX, new THREE.MeshToonMaterial({ map: stripeTexture('#f6f6fa', arena.obstacle, 3) }));
346:   bar.scale.set(r, r, r);
347:   bar.scale.x = r;
348:   // using cylinder axis X geometry: scale radius in Y/Z and length in X
349:   bar.scale.set(len, r, r);
350:   group.add(bar);
351:   [-1, 1].forEach(s => mesh(group, G.cylAxisX, toonMat(arena.platformSide), [s * len / 2, 0, 0], [0.12, r * 1.02, r * 1.02]));
352:   const span = opt.span || 26;
353:   const speed = opt.speed || 6.8;
354: 
355:   return {
356:     type: 'roller', group, power: 7,
357:     update(dt, t) {
358:       const prog = ((t * speed / span + (opt.phase || 0)) % 1);
359:       group.position.z = opt.zFar + prog * span;
360:       group.rotation.x = -prog * span / r;
361:     },
362:     hit(pos, radius, height) {
363:       const dx = pos.x - group.position.x, dz = pos.z - group.position.z;
364:       const rr = r + radius;
365:       if (dx * dx + dz * dz > rr * rr) return null;
366:       if (pos.y > group.position.y + r * 0.85) return null;
367:       if (pos.y + height < group.position.y - r) return null;
368:       const nz = dz / (Math.hypot(dx, dz) || 1);
369:       return { nx: dx / (Math.hypot(dx, dz) || 1) * 0.75, nz: 0.75 + nz, power: 11.5, up: 4.0, label: 'FLATTENED BY A ROLLER' };
370:     }
371:   };
372: }
