428:   mesh(group, G.box, toonMat(arena.platformSide), [-4.2, pivotH * 0.5, 0], [0.55, pivotH, 0.55]);
429:   mesh(group, G.box, toonMat(arena.platformSide), [4.2, pivotH * 0.5, 0], [0.55, pivotH, 0.55]);
