457: // ---------------------------------------------------------------------------
458: // POP-UP BOMPER - alternating, retractable impact columns
459: // ---------------------------------------------------------------------------
460: function bumper(opt, arena) {
461:   const group = new THREE.Group();
462:   group.position.set(opt.x || 0, opt.top, opt.z);
463:   const r = opt.radius || 0.72;
464:   const height = opt.height || 2;
465:   const phase = opt.phase || 0;
466:   const period = opt.period || 1.9;
467:   const column = new THREE.Group();
468:   group.add(column);
469:   mesh(column, G.cyl, toonMat(arena.platformSide), [0, -0.45, 0], [r * 1.15, 0.9, r * 1.15]);
470:   mesh(column, G.sphere, toonMat(arena.obstacle), [0, 0, 0], [r, r, r]);
471:   glow(column, arena.accent, [0, r * 0.55, 0], 0.16);
472: 
473:   return {
474:     type: 'bumper', group, power: 13,
475:     update(dt, t) {
476:       const p = ((t / period + phase) % 1);
477:       const raised = p < 0.58;
478:       column.position.y = raised ? height * (0.5 + 0.5 * Math.sin(p * Math.PI / 0.58)) : -0.8;
479:       column.visible = raised;
480:     },
481:     hit(pos, radius, height) {
482:       if (!column.visible) return null;
483:       const cx = group.position.x;
484:       const cy = opt.top + column.position.y;
485:       const dx = pos.x - cx, dz = pos.z - opt.z;
486:       if (dx * dx + dz * dz > (r + radius) ** 2) return null;
487:       if (pos.y > cy + r || pos.y + height < cy - r) return null;
488:       const len = Math.hypot(dx, dz) || 1;
489:       return { nx: dx / len, nz: dz / len + 0.7, power: 13, up: 5, label: 'Popped by a BUMPER!' };
490:     }
491:   };
492: }
