global.update = (dt, t, player, racing) => {
  const pProgress = Math.max(0, Math.min(1, (startZ - player.pos.z) / totalDistance));
  global.playerProgress = pProgress;
  for (const b of bots) {
    if (racing && !b.finished) {
      b.t = (b.t || 0) + dt;
      // Keep a narrow pace range, with real slowdowns for hits and stumbles.
      const pace = b.stumble > 0 ? 0.2 : 1.08;
      b.progress = Math.min(1, b.progress + dt * pace / b.finishTime);
      if (b.progress >= 1) {
        b.progress = 1;
        b.finished = true;
        b.finishTime = b.t;
      }
    }

    const z = startZ - b.progress * totalDistance;
    b.z = z;
    let x = b.laneOffset + (racing ? Math.sin(t * 0.8 + b.phase) * 0.7 : 0);
    x += b.xKick || 0;
    if (b.progress > 0.94) x *= Math.max(0.15, (1 - b.progress) / 0.06);

    b.stumbleTimer -= racing ? dt : 0;
    b.hitCooldown = Math.max(0, (b.hitCooldown || 0) - dt);
    b.xKick = (b.xKick || 0) * Math.max(0, 1 - dt * 2.8);
    if (b.stumbleTimer <= 0 && !b.finished && racing) {
      b.stumble = Math.max(b.stumble, 0.55 + Math.random() * 0.5);
      b.stumbleTimer = 3 + Math.random() * 5;
    }
    b.stumble = Math.max(0, b.stumble - dt);

    let groundInfo = course.groundAt(x, z, b.y + 0.7);
    let groundTop = groundInfo ? groundInfo.top : null;
    const grounded = groundTop !== null && !b.airborne && b.y <= groundTop + 0.48;

    if (grounded) {
      b.y = groundTop;
      b.jumpVy = 0;
      b.lastGround = groundTop;
      // Jump near a real gap or when a hazard is immediately in the bot's lane.
      const platform = groundInfo.platform;
      const atEdge = z - platform.zFront < 3.2;
      const nextGround = course.groundAt(x, z - 3.4, b.y + 1.1);
      const hazardAhead = racing && course.hitObstacle
        ? course.hitObstacle({ x, y: b.y, z: z - 1.8 }, 0.45, 1.5)
        : null;
      if ((atEdge && !nextGround) || (hazardAhead && b.stumble <= 0)) {
        b.airborne = true;
        b.jumpVy = 7.6;
      }
    } else {
      b.airborne = true;
      b.jumpVy -= 16 * dt;
      b.y += b.jumpVy * dt;
      // Re-query below the bot so it can land on lower platforms as well.
      groundInfo = course.groundAt(x, z, b.y + 0.12);
      groundTop = groundInfo ? groundInfo.top : null;
      if (groundTop !== null && b.jumpVy <= 0 && b.y <= groundTop) {
        b.y = groundTop;
        b.jumpVy = 0;
        b.airborne = false;
        b.lastGround = groundTop;
      }
    }

    // Fall recovery follows the same checkpoint progression as the player.
    if (b.progress > 0.97) b.rig.root.visible = true;
    for (const cp of course.checkpointsSorted) {
      if (b.progress >= (startZ - cp.z) / totalDistance) b.checkpoint = cp;
    }
    if (b.y < -2.25) {
      const cp = b.checkpoint;
      b.progress = cp ? Math.max(0, (startZ - cp.respawn.z) / totalDistance) : 0;
      b.y = cp ? cp.respawn.top : 0;
      b.z = cp ? cp.respawn.z : startZ;
      b.airborne = false;
      b.jumpVy = 0;
      b.stumble = Math.max(b.stumble, 0.7);
    }

    // Apply obstacle responses at the bot's actual position, not only ahead.
    if (racing && !b.finished && b.hitCooldown <= 0 && course.hitObstacle) {
      const hit = course.hitObstacle({ x, y: b.y, z: b.z }, 0.45, 1.5);
      if (hit) {
        b.hitCooldown = 0.65;
        b.stumble = Math.max(b.stumble, 0.45 + (hit.power || 8) * 0.025);
        b.xKick = (b.xKick || 0) + (hit.nx || 0) * Math.min(2.2, 0.6 + (hit.power || 8) * 0.07);
        if (hit.up > 0 && !b.airborne) {
          b.airborne = true;
          b.jumpVy = hit.up;
        }
      }
    }

    if (b.stumble > 0) {
      b.rig.body.rotation.z = Math.sin(t * 25) * 0.35;
      b.rig.body.rotation.x = Math.sin(t * 19) * 0.2;
    } else {
      b.rig.body.rotation.z *= (1 - Math.min(1, dt * 8));
      b.rig.body.rotation.x *= (1 - Math.min(1, dt * 8));
    }
    b.rig.setPose(b.finished ? 'celebrate' : (b.airborne ? 'jump' : 'run'), t + b.phase, b.stumble > 0 ? 0.45 : 0.85, 0.7);
    b.group.position.set(x, b.y, b.z);
    b.group.rotation.y = Math.sin(t * 1.2 + b.phase) * 0.15;
  }

  const entries = [
    { id: 'player', progress: pProgress, finished: player.finished, time: player.finishTime || 999 },
    ...bots.map(b => ({ id: b.id, progress: b.progress, finished: b.finished, time: b.finishTime }))
  ];
  entries.sort((a, b) => {
    if (a.finished && b.finished) return a.time - b.time;
    if (a.finished) return -1;
    if (b.finished) return 1;
    return b.progress - a.progress;
  });
  const rank = entries.findIndex(e => e.id === 'player') + 1;
  bots.forEach(b => { b.rank = entries.findIndex(e => e.id === b.id) + 1; });
  return { rank, total: entries.length };
};

