171:       const a = this.menu.orbit;
172:       const cam = this.camera;
173:       const target = new THREE.Vector3(2.4, 1.5, -1.5);
174:       cam.position.set(5.4 + Math.sin(a) * 10.5, 4.1 + Math.sin(t * 0.2) * 0.3, -1.5 + Math.cos(a) * 10.5);
