246:         player.vel.x += wob * dt * (player.state === 'tumble' ? 0 : 1);
247:       }
248:       if (platform.kind === 'disc' && platform.spinRate) {
249:         const dx = player.pos.x - platform.x;
250:         const dz = player.pos.z - platform.z;
251:         const tang = platform.spinRate * (1.15 - phys.balanceGrip * 0.45);
252:         player.vel.x += -dz * tang * dt;
253:         player.vel.z += dx * tang * dt;
254:       }
255:     }
256: 
257:     // jump
258:     if (player.jumpBuffer > 0 && (player.grounded || player.coyote > 0) && player.state !== 'tumble' && player.diveTimer <= 0) {
259:       player.vel.y = phys.jumpVel * (player.stamina > 0.15 ? 1 : 0.85);
260:       player.grounded = false;
261:       player.coyote = 0;
262:       player.jumpBuffer = 0;
263:       player.state = 'jump';
264:       player.stamina = Math.max(0, player.stamina - 0.035);
265:       player.callbacks.onJump?.();
266:     }
267: 
268:     // gravity
269:     if (!player.grounded) {
270:       player.vel.y -= GRAVITY * dt;
271:       player.vel.y = Math.max(MAX_FALL, player.vel.y);
272:     }
273: 
274:     // integrate
275:     const prevY = player.pos.y;
276:     player.pos.x += player.vel.x * dt;
277:     player.pos.z += player.vel.z * dt;
278:     player.pos.y += player.vel.y * dt;
279: 
280:     // ground snap for landing (crossing test prevents fast-fall tunnelling)
281:     const g2 = course.groundAt(player.pos.x, player.pos.z, prevY + 0.45);
282:     if (!player.grounded && player.vel.y <= 0.1 && g2) {
283:       const top = g2.top;
284:       if (player.pos.y <= top + 0.05 && prevY >= top - 0.12) {
285:         player.pos.y = top;
286:         player.vel.y = 0;
287:         player.grounded = true;
288:         player.groundTop = top;
289:         player.groundPlatform = g2.platform;
290:         if (player.state !== 'tumble') {
291:           player.state = player.diveTimer > 0 ? 'dive' : 'run';
292:           player.callbacks.onLand?.(prevY - top);
293:         } else {
294:           player.tumbleTimer = Math.min(player.tumbleTimer, 0.45);
295:         }
296:       }
297:     }
298:     if (player.grounded && g2 && Math.abs(player.pos.y - g2.top) < 0.5) {
299:       player.pos.y = g2.top;
300:       player.groundTop = g2.top;
301:       player.groundPlatform = g2.platform;
302:     }
303:     if (player.grounded) player.lastGroundedY = player.pos.y;
304: 
305:     // dive timer
306:     if (player.diveTimer > 0) {
307:       player.diveTimer -= dt;
308:       if (player.grounded) {
309:         player.vel.x *= (1 - dt * 1.8);
310:         player.vel.z *= (1 - dt * 1.8);
311:       }
312:       if (player.diveTimer <= 0) {
313:         player.state = player.grounded ? 'run' : 'jump';
314:       }
315:     }
316: 
317:     // tumble / getup
318:     if (player.state === 'tumble') {
319:       player.tumbleTimer -= dt;
320:       if (player.tumbleTimer <= 0 && player.grounded) {
321:         player.state = 'getup';
322:         player.getUpTimer = phys.getUpTime;
323:         player.callbacks.onRecover?.();
324:       }
325:       // random spin
326:       player.spin.x += player.spin.ax * dt;
327:       player.spin.z += player.spin.az * dt;
328:       player.spin.ax *= (1 - dt * 1.4);
329:       player.spin.az *= (1 - dt * 1.4);
330:     } else {
331:       player.spin.x *= (1 - Math.min(1, dt * 9));
332:       player.spin.z *= (1 - Math.min(1, dt * 9));
333:     }
334:     if (player.state === 'getup') {
335:       player.getUpTimer -= dt;
336:       if (player.getUpTimer <= 0) player.state = 'run';
337:     }
338: 
339:     // stamina
340:     if (sprinting) {
341:       player.stamina = Math.max(0, player.stamina - phys.staminaDrain * dt * 1.5);
342:     } else {
343:       player.stamina = Math.min(1, player.stamina + phys.staminaRegen * dt * (player.state === 'tumble' ? 0.4 : 1));
344:     }
345: 
346:     // ---------------- hazards ----------------
347:     const hit = course.hitObstacle(player.pos, phys.radius, phys.height);
348:     if (hit) {
349:       player.tumble(hit);
350:     }
351: 
352:     const launched = course.tryLaunch(player.pos, player.pos.y);
353:     if (launched) {
354:       player.vel.y = launched.power;
355:       player.vel.z = -Math.max(6.5, Math.abs(player.vel.z) + launched.forward);
356:       player.grounded = false;
357:       player.state = 'jump';
358:       player.callbacks.onLaunch?.();
359:     }
360: 
361:     // checkpoints
362:     for (const cp of course.checkpointsSorted) {
363:       if (cp.index > player.checkpointIndex && player.pos.z < cp.z) {
364:         player.checkpointIndex = cp.index;
365:         player.checkpoint = cp;
366:         player.callbacks.onCheckpoint?.(cp);
367:       }
368:     }
369: 
370:     // finish
371:     if (!player.finished && player.pos.z <= course.finishZ) {
372:       player.finished = true;
373:       player.state = 'finished';
374:       player.vel.set(0, 0, 0);
375:       player.callbacks.onFinish?.();
376:     }
377: 
378:     // water
379:     if (player.pos.y < WATER_Y + 0.05) {
380:       player.splash();
381:       player.render(0.1, dt, time);
382:       return;
383:     }
384: 
385:     // reset if fallen way out of bounds
386:     if (player.pos.y < WATER_Y - 30 || Math.abs(player.pos.x) > 120) {
387:       player.splash();
388:     }
389: 
390:     // yaw
391:     const planarSpeed = Math.hypot(player.vel.x, player.vel.z);
392:     player.speed = planarSpeed;
393:     if (planarSpeed > 0.35 && player.state !== 'tumble') {
394:       const targetYaw = Math.atan2(-player.vel.x, -player.vel.z);
395:       let diff = targetYaw - player.yaw;
396:       while (diff > Math.PI) diff -= Math.PI * 2;
397:       while (diff < -Math.PI) diff += Math.PI * 2;
398:       player.yaw += diff * Math.min(1, dt * 14);
399:     }
400:     player.moveAmt = Math.min(1, planarSpeed / phys.moveSpeed);
401: 
402:     // blink while invulnerable
403:     player.rig.root.visible = !(player.invuln > 0 && Math.sin(player.runTime * 32) > 0.55);
404:     if (player.finished) player.rig.root.visible = true;
405: 
406:     player.render(dt, dt, time);
407:   };
408: 
409:   player.render = (dt, rawDt, time = 0) => {
410:     const p = player;
411:     p.group.position.copy(p.pos);
412:     p.group.rotation.y = p.yaw;
413:     if (p.markerMesh) {} else {
414:       p.markerMesh = p.group.children.find(o => o.isGroup && o !== p.rig.root);
415:     }
416:     if (p.markerMesh) {
417:       p.markerMesh.position.y = p.rig.height + 0.55 + Math.sin(time * 3) * 0.09;
418:       p.markerMesh.rotation.y = time * 1.5;
419:       p.markerMesh.visible = !p.finished && p.state !== 'splash';
420:     }
421: 
422:     let animState = p.state;
423:     if (p.state === 'run') animState = p.moveAmt < 0.08 ? 'idle' : 'run';
424:     if (p.state === 'jump' && !p.grounded) animState = 'jump';
425:     if (p.finished) animState = 'celebrate';
426: 
427:     p.rig.setPose(animState, time, p.moveAmt, Math.min(1, p.speed / 10));
428:     // lean
429:     if (p.state === 'run' && p.grounded) {
430:       p.rig.body.rotation.z = -(p.vel.x / phys.moveSpeed) * 0.18;
431:       p.rig.body.rotation.x += Math.min(0.16, p.speed * 0.014);
432:     }
433:     if (p.state === 'tumble') {
434:       p.rig.body.rotation.x = p.spin.x;
435:       p.rig.body.rotation.z = p.spin.z;
436:       p.rig.body.position.y += Math.abs(Math.sin(time * 12)) * 0.22;
437:     }
438:     if (p.state === 'getup') {
439:       const q = 1 - Math.max(0, p.getUpTimer / Math.max(0.01, phys.getUpTime));
440:       p.rig.body.rotation.x = 1.2 * (1 - q);
441:       p.rig.body.position.y = 0.28 * (1 - q);
442:     }
443:     if (p.state === 'splash') {
444:       p.rig.body.rotation.z = Math.sin(time * 12) * 0.5;
445:       p.rig.body.rotation.x = Math.sin(time * 9) * 0.4;
446:     }
447: 
448:     // airborne shadow
449:     const sh = p.rig.shadow;
450:     if (p.grounded) {
451:       sh.position.y = 0.025;
452:       sh.material.opacity = 0.3;
453:     } else {
454:       const g = course.groundAt(p.pos.x, p.pos.z, p.pos.y);
455:       if (g) {
456:         const hgt = Math.max(0, p.pos.y - g.top);
457:         sh.position.y = -hgt + 0.03;
458:         sh.material.opacity = Math.max(0.05, 0.3 - hgt * 0.06);
459:       } else {
460:         sh.material.opacity = 0.05;
461:         sh.position.y = -3;
462:       }
463:     }
464:     // stamina-based visual breathing
465:     if (p.state === 'idle' && p.stamina < 0.3) {
466:       p.rig.body.position.y += Math.sin(time * 8) * 0.015;
467:     }
468:   };
469: 
470:   return player;
471: }

