  const warnGlow = glow(group, arena.accent, [0, 0.25, 0], 0.4) maybe.

  let headY = lift;
  return {
    type:'crusher', group, power: 18,
    update(dt,t) {
      const p = ((t/period + phase) % 1);
      let y;
      if (p < 0.62) y = lift * (0.85 + 0.15*Math.sin(t*2)); // idle raised
      else if (p < 0.74) { const q=(p-0.62)/0.12; y = lift*(1-q) + 1.1*q; pressure slam eased }
      else if (p < 0.86) y = 1.1;
      else { const q=(p-0.86)/0.14; y=1.1*(1-q)+lift*q; }
      head.position.y = y;
      head.rotation.z = p>0.8? ...; 
      // telegraph: decal opacity pulsing in idle, bright before slam
      const telegraph = p < 0.62 ? 0.2 + 0.15*Math.sin(t*8) : 0.7;
      decal.material.opacity = telegraph;
