    hit(pos, radius, height) {
      const pressBottom = head.position.y - 0.55;
      if (pos.y + height < pressBottom - 0.2) return null; // below press
      if (pos.y > head.position.y + 0.7) return null;
      const dx=pos.x-(opt.x||0), dz=pos.z-opt.z;
      if (Math.abs(dx) > size/2+radius || Math.abs(dz) > size/2+radius) return null;
      return { nx: dx/(Math.abs(dx)+0.001)*0.7, nz: 0.8, power: 19, up: 6, label:'FLATTENED BY THE CRUSHER!' };
    }
  };
}
