bumpers(p, n = 3) {
  const xs = n === 1 ? [p.x] : [-4.2, 0, 4.2].slice(0, n).map(v => v + p.x);
  for (let i = 0; i < n; i++) {
    const zz = p.zBack - p.d * (i + 0.5) / n;
    addObs('bumper', {
      x: xs[i], z: zz, top: p.top, radius: 0.78,
