function chooseLane(b, t, player) {
  const half = Math.max(1.1, b.halfW);
  const preferred = clamp(b.laneFraction * half, -half, half);
  let best = b.x;
  let bestScore = -Infinity;
  let anySafe = false;

  for (const f of LANE_FRACTIONS) {
